C=[]
def c(n,its,scans,lines,his,statement,status,cl,fate,refs,queries,comp='',confidence='high',source='MPL_31_002-051',date='Seminar dates do not date this undated leaf; publication date given with the matched reference.'):
 ident=f'CL-SA12-{n}';it=[f'SA12-{x}' for x in its]
 C.append(dict(id=ident,items=it,cote='31',scans=scans,lines=source+'_transcription.tex:'+lines,his_statement=his,statement=statement,status_on_pages=status,computation=comp or 'No numerical calculation. The stated proof mechanism and its hypotheses were compared with the supplied text and the cited source; this is not a new formal proof.',**{'class':cl},fate=fate,fate_date=date,present_status='As of 2026-11-19: '+fate,refs=refs,confidence=confidence,query_ids=queries))

c(401,[401],[2,3],'3–34','Two dimensions, cd_p and cd′_p, are defined for flat sheaves and finite commutative p-groups.','For the site whose coverings are finite faithfully flat maps, the supremum over finite representable commutative p-primary coefficients is at most the supremum over all p-primary abelian sheaves. Equality with that supremum, or with the big fppf site, is not asserted or proved.','open on the pages','F','The exact finite-flat-site comparison is not identifiable as a theorem here. Modern fppf results in Milne ADT III0 and the finite-group structure theorem do not identify these two suprema without a site-comparison argument.',['MilneADT','MilneAG2017'],['S31-5.1','S31-5.2','S31-5.3','S31-5.4'],confidence='medium')
c(402,[402],[3],'18–34','G′⊂G″⊂G, with G″=G⁰; reduction to three kinds of finite p-groups.','For a finite commutative p-power group scheme over a field of characteristic p, connected–étale and multiplicative–unipotent structure give a filtration with étale, connected unipotent, and connected multiplicative-type factors. Short exact sequences of flat abelian sheaves reduce uniform high-degree vanishing to these factors.','proof sketched','A','This is the finite commutative specialization of the group-scheme structure developed in SGA3; Milne AG16.13 supplies the multiplicative subgroup/unipotent quotient, while the connected–étale sequence is treated in AG chapter5. The filtration does not require a product decomposition over an imperfect field.',['MilneAG2017','SGA3IX'],['S31-5.1','S31-5.2','L31-structure'])
c(403,[403],[5],'72–74','cd for étale p-primary coefficients is 0 or1; toute is struck.','For a field k of characteristic p, cd_p(k)≤1. It equals0 exactly when every finite separable extension has degree prime to p, equivalently its absolute Galois group is pro-prime-to-p. Otherwise it equals1. The universal quantifier is a reconstruction of the struck wording.','stated without proof','E','Artin–Schreier and additive acyclicity prove the upper bound; SGA4 X5.1 and Stacks0A3J/0A3K state it. The zero-dimensional criterion follows from vanishing of p-cohomology on open subgroups.',['SGA4III','Stacks0A3J','Stacks0A3K'],['L31-field','S31-5.4'],date='Artin–Schreier theory predates these notes; SGA4 seminar1963–64, tomeIII1973. Exact earliest formulation not established here.')
c(404,[404],[5,7],'76–102;136–146','nul pour i>n, et p-divisible si i=n','For n≥0, vanishing H^i(k,G)=0 for i>n and every finite multiplicative-type p-group G is equivalent to: for every k-torus T, H^i(k,T){p}=0 for i>n and H^n(k,T) is p-divisible. These are flat cohomology groups; for smooth T they agree with étale cohomology.','proof sketched','C','The displayed Kummer long exact sequence and torus resolutions support the criterion. Modern flat cohomology and multiplicative-type structure were located, but no opened source was found that states precisely this finite-flat-site formulation for every n. The argument is valid after the modern flat-sheaf interpretation and the prime-to-p reduction recorded separately.',['MilneADT','SGA3IX'],['S31-5.1','S31-5.2','S31-5.3','L31-structure'],comp='Reconstructed exact segment H^(i−1)(T)/p -> H^i(T[p]) -> H^i(T)[p]. Vanishing for all p-power kernels gives divisibility at n and absence of p-primary torsion above n; converse uses a torus embedding and the written norm reduction.',confidence='medium')
c(405,[405,406],[5,7,9],'96–102;148–170;207–226','Passing to k′ of degree prime to p; the earlier surjectivity attempt is deleted.','For a finite splitting Galois group Γ of a multiplicative p-group, pass to the fixed field of a p-Sylow. The resulting extension degree is prime to p, so restriction is injective on p-primary cohomology via corestriction. Over the new field, the Cartier-dual finite p-module has a filtration with trivial Fp factors. For a torus T, [k′:k] is the composite T→Res(T_k′)→T.','corrected by himself later: scan7 abandoned argument replaced on scan9','E','The ingredients are restriction–corestriction, Shapiro, and the unique simple module of a finite p-group over Fp. They establish the replacement mechanism; they do not validate the crossed-out p-divisibility argument on scan7.',['MilneCFT','MilneAG2017'],['S31-5.3','L31-group'],comp='If d=[k′:k] is prime to p, multiplication by d is an automorphism on every p-primary group. Thus cor∘res=d implies res injective. A nonzero finite Fp[P]-module has nonzero invariants; induction yields a trivial-constituent filtration.')
c(406,[407],[7],'141–146','The restriction-of-scalars identity ends with H^i(k,G).','For finite separable k′/k and an abelian group/sheaf G′, H^i(k,Res_k′/k G′)≅H^i(k′,G′) in the applicable Galois/flat setting. The manuscript right-hand field and coefficient do not match.','false as transcribed: undefined right-hand coefficient','E','Shapiro is standard before the manuscript. The corrected right-hand expression is mathematical reconstruction, reserved for scan checking; it is not an alteration of the diplomatic text.',['MilneCFT','MilneADT'],['L31-group','S31-5.3'])
c(407,[409],[9],'228–231','The radicial additive case has dimension0 or1 according to perfection.','The flat exact sequence 0→α_p→Ga→Ga→0, with Frobenius, gives H¹(k,α_p)=k/k^p and H^i(k,α_p)=0 for i≥2. Finite connected unipotent commutative groups are handled by their additive-type filtration; over a perfect field every finite connected torsor has a rational point, giving the dimension0 case.','proof sketched','A','The additive calculation is standard flat cohomology (Milne ADT III0); group filtrations belong to SGA3. No claim that α_p is an étale sheaf substitute is made.',['MilneADT','MilneAG2017'],['S31-5.2','S31-5.3','L31-structure'],comp='Long exact sequence: H⁰Ga=k, Frobenius image k^p, all higher Ga-cohomology on a field vanish; quotient=k/k^p, remaining positive terms zero.')
c(408,[410],[4,6],'40–68;106–123','Homomorphismes centraux; agreement near a fiber.','Let H be finite type and of multiplicative type over S, and G an S-group. Assume S locally noetherian or G finitely presented. If u,v:H→G agree at s and u_s is central, then they agree on a neighborhood of s. The page assumes the stronger global centrality of u.','proof sketched','A','Exact published match SGA3 IX5.1, with weaker fiber centrality; proof uses IX3.4, finite torsion and density IX4.7, then approximation.',['SGA3IX'],['S31-7.1','L31-rigidity'],date='SGA3 seminar1962–64; first published tomeII1970; opened2009 edited version.')
c(409,[412],[6,8],'124–133;174–195','Trivial homomorphisms; the triviality locus is open and closed.','Under the preceding finite-type H and local-noetherian/finitely-presented G alternatives, fiberwise triviality implies local triviality. If G is separated, the triviality locus is clopen. The transcribed repeated H is not the relevant finite-presentation or separatedness hypothesis.','proof sketched','A','SGA3 IX5.2–5.3 matches precisely and requires separatedness of G. The two H/G occurrences are listed in readings.',['SGA3IX'],['S31-7.1','L31-rigidity'])
c(410,[413],[6,8],'129–133;197–202','Subgroup version, struck in the retained text.','For multiplicative-type finite-type subgroup schemes H1,H2 of G, agreeing at s, with the centrality and ambient finiteness assumptions of IX5.1bis, equality holds on an open neighborhood.','withdrawn in the retained typescript; mathematical statement not disproved','A','The subgroup analogue is retained in published SGA3 IX5.1bis. Global cancellation of a reused sheet/heading is not evidence of a mathematical refutation.',['SGA3IX'],['S31-7.1','L31-rigidity'],confidence='medium')
c(411,[414],[18],'506–523','The functor of characters is an anti-equivalence.','Finite-type groups of multiplicative type over S correspond contravariantly to locally constant étale sheaves of finitely generated abelian groups (twisted constant groups), with quasi-isotriviality interpreted as étale local triviality.','stated with references on a globally struck reused sheet','A','SGA3 X5.1–5.6 is the direct published continuation. This is a classification statement, independent of global finite étale splitting.',['SGA3X'],['S31-7.2','L31-isotrivial'])
c(412,[414],[18],'523–546','Isom is open and closed in Hom; Aut is twisted constant.','For the finite-type multiplicative-type groups in the text, Hom is represented by the appropriate twisted constant scheme; the fiberwise isomorphism locus is clopen, hence Isom is a clopen subscheme, and Aut is twisted constant.','proof sketched on a globally struck reused sheet','A','SGA3 X5.6–5.8 gives the representability and clopen isomorphism construction. Check finite generation of the source character module when using finite-type Hom assertions.',['SGA3X'],['S31-7.2','L31-isotrivial'])
c(413,[415],[18,16,14],'532–546;432–476;363–400','Isotriviality and finite clopen pieces; finite cover from Isom.','With the base restrictions explicitly separated in SGA3 X5.11, a finite-type constant-type group H is split by a finite étale surjection iff its character scheme is assembled from finite clopen pieces; finite connected components give another criterion under local noetherianity.','proof sketched on globally struck reused sheets','A','SGA3 X5.11 reproduces the construction. The2009 editor flags a missing verification for the converse with a not-finitely-generated auxiliary R; this run does not erase that qualification.',['SGA3X'],['S31-7.2','L31-isotrivial'],confidence='medium')
c(414,[416],[16],'440–454','A quasi-compact closed part of a twisted constant scheme is finite.','If P is twisted constant over S and Z⊂P is closed with Z→S quasi-compact, then Z→S is finite: after an fpqc trivialization and affine localization, quasi-compactness places Z in finitely many copies of S.','proof sketched','A','SGA3 X5.12 is the exact elementary lemma. Finite descent and the closed-subscheme condition are essential.',['SGA3X'],['S31-7.2','L31-isotrivial'])
c(415,[417],[14,12],'385–400;280–303','One finite fiber forces finiteness over connected S.','If S is connected locally noetherian, P a quasi-isotrivial twisted constant S-scheme, and Z⊂P clopen, then finiteness of one fiber Z_s implies Z finite over S.','proof sketched','A','SGA3 X5.13: the finite-fiber locus is clopen, as checked after étale local trivialization. Connectedness is indispensable for the one-fiber conclusion.',['SGA3X'],['S31-7.2','L31-isotrivial'])
c(416,[418],[14],'376–384','Countable finite clopen exhaustion, without restrictions on S.','For H finite type and constant type over arbitrary S, the note says H is isotrivial iff its character scheme is a union of a sequence of finite clopen S-schemes.','stated without proof','C','Exact wording survives in SGA3 X5.11bis. The opened2009 reedition footnote44 explicitly requests verification of the converse. This evidence supports a genuine proof question, not a claim that the converse is false or still globally open in2026.',['SGA3X'],['S31-7.2','L31-isotrivial'],confidence='medium')
c(417,[419],[12],'304–320','The normal-base argument works for geometrically unibranch bases.','If S is locally noetherian and geometrically unibranch, components of a quasi-isotrivial twisted constant scheme are finite over S; finite-type multiplicative-type groups are locally isotrivial, and under the stated connectedness/quasi-compactness conditions globally isotrivial.','proof sketched','A','SGA3 X5.14–5.16 gives the geometric-unibranch formulation. Its editorial note45 expressly says the original normal proof applies verbatim and was rewritten accordingly.',['SGA3X'],['S31-7.2','L31-isotrivial'])
c(418,[421,423],[11,15],'240–279;401–431','Construction by pushout of E_n and A along (ξ,f).','For A noetherian, f regular, g regular modulo f and A/(f,g)≠0, construct E_n=(E_(n−1)⊕A)/A(ξ_(n−1),f) with the chosen ξ̄=(ḡ,0). Transition maps are injective; E_n is killed by f^n and its f-annihilator filtration has successive quotient A/f.','proof sketched','C','The module construction itself checks by the written pushout induction. SGA2 XIII1.1 explains the old cofini context; later Hartshorne-cofiniteness statements concern a stronger Ext condition and are not an identification of this exact construction.',['SGA2','TakahashiWakasugi'],['S31-topics1.2','L31-cofini'],comp='programs/check_calculations.py; outputs/calculations.json#module_chain. The concrete C[[x,y]] model verifies injective transitions, annihilators and quotient behavior; the general pushout proof uses regular f and g, not a finite sample alone.')
c(419,[424],[13,15],'323–362;416–431','hη_n=0 forces h∈fA.','The inference is justified when η_n corresponds to a regular element of A/f; mere nonzeroness is insufficient. The chosen g supplies regularity. For A=C[[x,y]], x e1=0 and x ej=−y e_(j−1) imply x^(n−1)(y e_n)=(-1)^(n−1)y^n e1 and ann(e1)=(x).','proof sketched with an implicit regularity step','C','The local construction is valid after making its induction hypothesis explicit. No independently published exact example was located; the elementary reconstruction is fully recorded.',['SGA2'],['S31-topics1.2','L31-cofini'],comp='programs/check_calculations.py; outputs/calculations.json#module_chain. Nonzero is not regular: in B=k[u,v]/(uv), η=u≠0 but vη=0.')
c(420,[426],[17],'477–503','Passing to the limit yields (B/g)^(N).','For B=A/f and the stated transition maps, E_n/fE_n≅B⊕(B/g)^(n−1), and the filtered colimit is ⊕_(N) B/g. In the model x acts as −y times a unilateral shift, so xM=yM.','proof sketched','C','The direct-limit calculation is valid; its conclusion exhibits the quotient-finiteness failure relevant to the old definition. The exact manuscript example was not found in later literature.',['SGA2','TakahashiWakasugi'],['S31-topics1.2','L31-cofini'],comp='programs/check_calculations.py; outputs/calculations.json#module_chain. General argument: each old free generator becomes a torsion summand at the next stage, and every eventual generator survives independently modulo g.')
c(421,[421],[11,17],'240–279;477–503','The module is f-cofini, yet M/fM is not finite.','Under SGA2’s old definition, f-power-torsion M is f-cofini if Hom_A(A/f,M) is finite. The constructed M satisfies this, while M/fM is not finite. Under Hartshorne’s later definition requiring all Ext groups finite, M is not f-cofinite, since Ext¹_A(A/f,M)=M/fM.','proved by the construction, with historical terminology needed','A','SGA2 XIII1.1 explicitly defines cofini using Hom only and observes failure of quotient stability. The new definition is documented by Takahashi–Wakasugi§1 and its reference to Hartshorne1969/70. These two assertions are compatible.',['SGA2','TakahashiWakasugi'],['S31-topics1.2','L31-cofini'],comp='Two-term free resolution 0→A --f→ A→A/f→0 gives Hom=M[f], Ext¹=M/fM, higherExt0; saved concrete module certificate.',confidence='high')
c(422,[427],[20,22],'555–614;629–660','Nonreal fields, real points and finite2-cohomological dimension.','For K finitely generated over Q, formal nonreality (−1 sum of squares), no ordering, no embedding into R, and no smooth real point on a suitable model are equivalent; this agrees with finite cd2(K). Scheme-level bounds must retain the nonreal residue-field hypothesis.','stated without proof','A','SGA4 X1 and X6 treats these real exceptions and finite-type bounds. The field-embedding equivalence uses finite generation and must not be generalized merely by finite transcendence degree.',['SGA4III','EisermannRoots'],['L31-field','S31-9.1'])
c(423,[428],[20],'583–590','A margin asks for finite transcendence degree instead.','The entire preceding equivalence list fails with only finite transcendence degree: take the real closure of Q(t) ordered by t>n for all n∈Z. It is orderable of trdeg1, but has no embedding into R, since a field embedding of real closed fields preserves the square-defined order.','open on the pages; proposed extension false as stated','E','Eisermann Remark2.4 and Theorem2.5 supply the order/real-closure facts; the explicit non-Archimedean counterexample is this run’s reconstruction.',['EisermannRoots'],['S31-9.1','L31-real'],comp='An embedding fixes all integers and preserves positive squares; t>n would hold in R for every n, contradicting the Archimedean property.')
c(424,[430],[20],'591–614','The scheme bound has a strict inequality.','For finite-type X/Z with the written nonreal condition, the upper bound is ≤2dimX+1, not <. SpecF3 has dimension0 and a nontrivial quadratic étale torsor.','false as transcribed','A','SGA4 X6.2 has the weak inequality. This is an ink-check candidate, not a decided transcription correction.',['SGA4III'],['L31-field','S31-9.1'],comp='programs/check_calculations.py; outputs/calculations.json#strict_cd_bound.')
c(425,[431],[22],'661–684','H^i(X,F)=H^i(X(C)/G,F), when X(R) is empty.','For X of finite type over R with no real points, comparison holds for torsion étale coefficients after complex analytification and descent along the free C2 action. The page’s unrestricted coefficient phrasing needs this qualification.','stated without proof','A','SGA4 XVI4.1 is the complex comparison theorem; descent for the free real involution gives the displayed quotient form. It does not support arbitrary integral or rational sheaves without further analysis.',['SGA4III'],['L31-comparison','S31-9.1'],confidence='medium')
c(426,[432],[22],'636–660','Cohomological dimension adds the transcendence degree.','For finite-type k′/k and ℓ≠char k, cdℓ(k′)=cdℓ(k)+trdeg(k′/k), except the orderable-to-nonorderable ℓ=2 case. The general upper inequality also holds. Dropping ℓ≠char k gives Fp→Fp(t), whose p-dimensions are both1.','false as transcribed without prime restriction','A','SGA4 X2.1 states precisely the prime restriction and real exception. The characteristic-p counterexample is independently checked using Artin–Schreier and a nontrivial constant p-extension.',['SGA4III','Stacks0A3J'],['L31-field','S31-9.2'],comp='For Fp(t), constants Fp² can be replaced by F_(p^p): a cyclic p constant extension is nontrivial, so cd_p≥1; Artin–Schreier gives≤1.')
c(427,[434],[23],'685–699','cd_l(K)≥cd_l(k)+dimA, with exceptions.','Let A be noetherian local, ℓ invertible in A, and assume no residue field is orderable when ℓ=2. The total ring of fractions satisfies cdℓR(A)≥cdℓk+dimA. For a domain this is the fraction field bound.','stated without proof','A','Exact theorem SGA4 X2.4. The opened proof is a chain of codimension-one specializations; mixed-characteristic formulations with ℓ noninvertible are not automatically included.',['SGA4III'],['L31-field','S31-9.2'])
c(428,[435],[23],'699–711','Catenary/Japanese and regular cases; an unnecessary-condition question.','The manuscript proposes weaker real-exception hypotheses under universal catenarity/Japanese conditions and a regularity variant. Its precise ℓ=2 and mixed-characteristic quantifiers remain compressed and partly overwritten.','open on the pages','C','SGA4 X2.4–2.5 confirms the clean invertible-prime nonorderable theorem. This run did not identify an opened result matching every surviving stronger clause. The statement is not promoted to an unrestricted regular-local equality.',['SGA4III','ILO2014'],['L31-field','S31-9.2','S31-4.3'],confidence='medium')
c(429,[436],[23],'687–710','Henselian is deleted; possible equality is cancelled.','The page withdraws a blanket henselian equality between fraction-field cd and residue-field cd plus dimension. For henselian DVRs, the equality holds under the prime/residue hypotheses in SGA4 X2.2. Higher-dimensional local statements require separate care.','corrected by himself later on the same page','A','SGA4 X2.2 gives the precise DVR case; ILO XVIII-B4.1.2 proves the strict-local integral fraction-field equality for invertible ℓ. These are replacements, not evidence that the cancelled broad wording was correct.',['SGA4III','ILO2014'],['L31-field','S31-4.3'])
c(430,[437],[23],'711–718','The real quadratic cone supplies an exception.','A=(R[x,y]/(x²+y²))_(x,y) is a one-dimensional singular local domain, with residueR and fraction fieldC(t). Thus cd2(k)=∞ and cd2(K)=1, disproving an unrestricted residue lower bound.','proof sketched','A','SGA4 X2.3 explicitly gives the henselized real quadratic example; the nonhenselian version here has the same fraction-field obstruction. Normality/regularity cannot be silently assigned to A.',['SGA4III','Stacks03RD','Stacks03R8'],['L31-field','L31-real'],comp='In Frac(A), i=y/x has square−1; x is transcendental, hence Frac(A)=C(x). x²+y² is irreducible overR, and embedding intoC(t) proves the domain/fraction assertions.')
c(431,[438],[25,27],'727–776;811–843','Lemme de Cartan: three acyclicity tests.','For a site and a family M stable under the fiber products appearing in chosen covers, vanishing higher Čech cohomology on a cofinal family of M-covers implies sheaf cohomology vanishing on M. Local effacement of the relevant classes can replace a stronger cofinality requirement in the proof.','proof sketched','A','SGA4 V4.3 and V5.9 develop the Čech criterion; Stacks03F9 states a precise modern version. Product closure means fiber products over the covered object, not mere unrelated categorical products.',['SGA4V','Stacks03F9'],['S31-6.1','S31-6.3','L31-cech'])
c(432,[439],[27,31],'811–865;1018–1043','The refinement-limit spectral sequence has vanishing E2^(0,q), q>0.','Local effacement makes the zeroth Čech cohomology of the higher-cohomology presheaf vanish after refinement. It does not say all E2^(p,q) with p≥0 vanish; the later explicit p=0 controls the uncertain earlier display.','proof sketched','A','The sheafification-zero property and Čech-to-derived spectral sequence occur in SGA4 V and Stacks03AZ. The source’s uncertain page index and p≥0/p=0 remain ink questions.',['SGA4V','Stacks03AZ'],['S31-6.1','L31-cech'],comp='Bidegrees of differentials recorded in programs/check_calculations.py#spectral_degrees; no assertion that E2 vanishes in every column.')
c(433,[440],[29,31],'918–972;1044–1079','The final implications replace the earlier equivalence.','The surviving schema is (ii bis)⇒(ii)⇒(i) and (iii bis)⇒(iii)⇒(i), with additional equivalences only after assumption(i). One must retain the stated refinement system and finite degree ranges.','corrected by himself later: scan29 opening replaced by scan31 final schema','A','SGA4 V comparison methods provide the framework. This run confirms the logical correction in the manuscript, without claiming all five draft conditions are unconditional equivalents.',['SGA4V','Stacks03AZ','Stacks03F9'],['L31-cech','S31-6.1'],confidence='medium')
c(434,[442],[29,31],'927–972;1028–1079','The proof replaces a total-degree region by 0<q≤n−1.','For a first-quadrant cohomological spectral sequence, the incoming differential to E_r^(n,0) has source(n−r,r−1), total degree n−1. The required vanishing region must match this boundary; the uncertain +1 in the earlier hypotheses is not resolved by the prose.','proof sketched with unresolved boundary','C','SGA4 V and Stacks03AZ give the spectral sequence, but no opened reference determines the ink of this draft’s +1. The degree computation is rechecked; full equivalence requires the final exact quantifiers.',['SGA4V','Stacks03AZ'],['L31-cech','S31-6.1'],comp='programs/check_calculations.py; outputs/calculations.json#spectral_degrees.',confidence='medium')
c(435,[444],[26],'779–791','Completion is fully faithful on locally free modules.','In SGA2 XII5.10: f:X→S proper, S locally noetherian, U⊂X open flat over S, and universal coherence of R^i j_*OU for i=0,1. After S′=SpecA with A noetherian complete for an idealJ, completion is fully faithful on finite-rank locally free modules on U′.','stated with preceding setup only partly retained','A','Exact match SGA2 XII5.10(i). The complete hypotheses are reconstructed from print, not read into the fragment. The index condition is i=0,1, not i≤2.',['SGA2'],['S31-8.3','L31-formal'])
c(436,[444],[26],'791–800','Every formal vector bundle comes from a coherent module, not necessarily locally free, hélas.','Under CL-SA12-435’s hypotheses, every finite-rank formal vector bundle on Uhat′ is the completion of a coherent module on U′. Local freeness of the algebraization is not asserted.','proof sketched','A','Exact match SGA2 XII5.10(ii), via coherent extension to Xhat′ and EGAIII existence. The hélas limitation survives in print.',['SGA2','EGAIII2'],['S31-8.3','L31-formal'])
c(437,[445],[26],'800–805','Purity or parafactoriality should yield equivalences.','The author expects suitable local purity/parafactorial hypotheses on geometric fibers to make completion an equivalence for finite étale covers/line bundles. The hypotheses are a programme, not a finished theorem on this leaf.','open on the pages','C','SGA2 XII5.11(1) retains the hope and refers to the preceding local Lefschetz results. Modern purity theorems support carefully specified cases; no universal nonproper equivalence follows merely from XII5.10.',['SGA2','SGA4III','ILO2014'],['S31-8.3','L31-formal','S31-topics1.4'],confidence='medium')
c(438,[446],[26],'805–809','Murre; Picard of nonproper schemes; Hilbert/Picard existence.','The page proposes using formal existence plus Murre’s work to represent certain nonproper Picard functors and to remove properness assumptions in broader representability theorems. No definite class of schemes or functors is specified.','open on the pages','C','SGA2 XII5.11 repeats the programme, with later editorial references to generalized Jacobians, Murre and Artin. Proper Picard representability does not settle all nonproper functors. Exact modern scope remains to be formulated before assigning a yes/no fate.',['SGA2','ILO2014'],['S31-topics1.4','S31-8.3','S31-10.1'],confidence='medium')
c(439,[448],[28],'866–881','Delete terms in EGA0III13.7.7, p78lines6,13,23.','The draft gives three deletion instructions. The published EGAIII2 erratum24 also adds finite generation of R^(n+1)T(A); the manuscript instruction is therefore not the complete published correction.','correction instructions, not a proof','A','EGAIII2 erratum24 (1963) is the exact printed comparison. Documentary deletion directives have been compared; no unseen ink has been changed.',['EGAIII2'],['L31-formal','S31-10.2'],date='EGAIII2 published fourth quarter1963, as stated in the opened edition.')
c(440,[449],[28],'882–917','Coherence, good filtration and uniform Mittag–Leffler.','Under the retained graded setup of SGA2 IX2.1, finiteness of K^i=⊕R^i f_*(J^mF/J^(m+1)F) in the three degrees n−1,n,n+1 implies coherence of R^n f_*F, formal comparison, a good induced filtration, and uniform Mittag–Leffler for the cohomology system.','stated with proof referred to EGA','A','Exact published proposition SGA2 IX2.1. All three adjacent degrees matter; finite generation of just the middle degree is not the written hypothesis.',['SGA2','EGAIII2'],['L31-formal','S31-10.2'])
c(441,[450],[30,32],'973–1017;1080–1085','Blank arrows in formal/ordinary comparisons; a degree n+1 question.','The t-power exact sequences and cohomological finiteness give the written ordinary-to-formal isomorphisms below n, injectivity at n, and formal-to-inverse-limit comparison in the displayed established range. The uncertain next-degree injectivity is a separate question.','proof sketched; boundary left open','C','SGA2 IX and XII plus EGAIII formal functions give the standard comparison. The incomplete boundary in the fragment is not filled by a generic formal-functions citation; the necessary Mittag–Leffler hypothesis is retained.',['SGA2','EGAIII2'],['L31-formal','S31-10.2'],comp='Reconstructed long exact sequence of 0→F --t^m→F→F/t^mF→0, followed by inverse limits; lim¹ vanishes only under the stated Mittag–Leffler control.',confidence='medium')
c(442,[451],[32],'1085–1101','Depth≥1 or≥2 yields faithful or fully faithful completion.','For the projective flat family and ample regular section in SGA2 XII2.4, fiberwise depth at closed points≥1 gives faithful completion of vector bundles near the hyperplane; depth≥2 gives full faithfulness. Morphisms are tested through Hom(F,G).','proof sketched, end cut off','A','SGA2 XII2.4 is the published match. The neighboring direct-image depth theorem supplies the missing continuation; the fragment itself ends before completion of its proof.',['SGA2'],['L31-formal','S31-10.2'])

c(443,[454],[35,36,37,38,39],'1111–1260','π₁(B)/im π₁(E) = G/S.','Let G act on a connected simplicial set E, B=E/G, and S be the normal subgroup generated by the vertex stabilizers. The image of π₁(E) in π₁(B) is normal and its quotient is G/S. For a simplicial complex with inversions, subdivision is needed before applying the vertex formulation.','proof sketched','B','Armstrong1965 proves the orbit fundamental-group formula when E is simply connected, using the subgroup generated by elements with fixed points. The manuscript treats the relative image as well; its path-lifting argument reconstructs that extension. No priority date for this undated leaf is inferred.',['Armstrong1965'],['S31-11.1','L31-orbit'],comp='The path from e to ge defines a class modulo projected loops from E. Concatenation gives a homomorphism, its kernel contains every vertex stabilizer, and edge-path lifting gives surjectivity. The covering in CL-SA12-444 identifies the kernel.',confidence='high')
c(444,[454],[36,37,38],'1155–1260','universel is crossed out and replaced by a covering corresponding to a subgroup.','The simplicial quotient E/S→E/G is a covering with deck group G/S and corresponds to im π₁(E). It is universal when E is simply connected, in particular contractible; it need not be universal for arbitrary connected E.','corrected by himself later: scan36 qualification, scans37–38 construction','B','The corrected covering interpretation agrees with the orbit-space argument in Armstrong1965. Taking G=1 and E a simplicial circle disproves unqualified universality.',['Armstrong1965'],['S31-11.1','L31-orbit'],comp='A lift of the first vertex uniquely determines the lift of each simplex for the free vertex action of G/S. For G=1,E=S¹, the identity covering retains fundamental group Z.')
c(445,[457],[38],'1246–1258','A simplex and a distinct translate are disjoint.','The assertion is false for closed geometric simplices. In the simplicial line with vertices Z, translation sends [0,1] to [1,2], sharing vertex1 despite trivial vertex stabilizers. The valid covering proof uses uniqueness of lifts over a specified vertex, or suitable open stars.','false as stated','E','Elementary simplicial topology already distinguishes interiors, closed simplices and evenly covered neighborhoods. Armstrong1965§1 checks triangulation conditions carefully. This run supplies the counterexample and the corrected local statement; it does not decide whether the ink meant interiors.',['Armstrong1965'],['S31-11.1','L31-orbit'],comp='Intersection [0,1]∩[1,2]={1}; every nonidentity translation fixes no vertex. Refined covering statement: CL-SA12-444.')
c(446,[458],[39],'1261–1285','The image of homology contains n times the quotient homology.','If finite G of order n acts on a simplicial set E and B=E/G, the orbit sum T([σ])=Σ_(g∈G)gσ is well defined on quotient simplicial chains, commutes with boundary, and p_*T=n·id. Thus nH_i(B,Z)⊂im H_i(E,Z). Stabilizers cause multiplicities rather than division.','proof sketched','E','This is the chain-level transfer identity; no freeness or division by stabilizer orders is required for this particular statement. Serre1953 provides the homological machinery used by the following consequence; the exact chain computation is independently rechecked here.',['Serre1953Classes'],['S31-11.2','L31-orbit'],comp='programs/check_calculations.py; outputs/calculations.json#orbit_transfer. Independence of the representative follows by reindexing G; boundary commutation follows from equivariance of every face map; projection gives n identical copies.')
c(447,[459],[39],'1286–1300','Higher homotopy groups are annulled by powers of n; finite is deleted.','If E is contractible and the subgroup S generated by all vertex stabilizers is finite of order n, every element of π_i(E/G), i>1, is killed by some power of n. No uniform exponent or finite cardinality is asserted.','proof sketched; argument ends after the homology step','B','E/S is simply connected by the preceding formula, and transfer kills its reduced integral homology by n. Serre1953 III theorem1, applied to the Serre class of n-primary torsion groups, then gives the homotopy conclusion. The manuscript leaves this last theorem application unstated.',['Serre1953Classes','Armstrong1965'],['S31-11.2','L31-orbit'],comp='The Serre class consists of groups in which each element is killed by a power of n; it is closed under subquotients, extensions, tensor and Tor. Induction through the mod-class Hurewicz theorem gives the claim.',date='Serre paper received1952-06-23, publishedSeptember1953; Armstrong received1964-09-09, published1965. Manuscript composition date not established.')
c(448,[461,463],[42],'1304–1341','Tr(B) contains1 iff every semilinear module is cohomologically trivial.','For finite G acting on a unital ring B, a trace-one element b∈B, Σ_g g(b)=1, implies Tate H^i(G,M)=0 for every semilinear B-module M and every integer i. Conversely universal vanishing in degree0, or in any one fixed Tate degree for all M, implies trace-one.','proof sketched','E','Higman’s relative-projectivity criterion, AKO IV4.2–4.3, identifies the trace-one splitting mechanism. Two-way dimension shifting, already in Serre1953Arithmetic, justifies the fixed-degree equivalence.',['AKO','HigmanBibliography','Serre1953Arithmetic','MilneCFT'],['S31-4.2','S31-11.3','L31-group'],comp='Multiplication by b is an endomorphism relative to the trivial subgroup; its conjugate sum is id_M. Thus M is a direct summand of an induced module, whose Tate cohomology vanishes. Conversely Tate H⁰(G,B)=B^G/Tr(B) detects1.')
c(449,[461,463],[42],'1322–1341','Every trace annihilates Tate cohomology.','For commutative B and A=B^G, the ideal Tr(B)⊂A annihilates Tate H^i(G,M) of every semilinear B-module M. In particular a unit trace implies vanishing.','proof sketched','E','The projection formula for restriction and corestriction proves the assertion, and is compatible with the trace-endomorphism version of Higman’s criterion. The scalar action requires the indicated central/commutative convention.',['MilneCFT','AKO'],['S31-11.3','L31-group'],comp='Multiplication by Tr(b) on M is Tr_1^G(m_b), so factors through an induced module in the stable category. Example B=Z with trivial C2 action: Tr(B)=2Z and Tate H⁰=Z/2.')
c(450,[461],[42],'1310–1321','Both directions of décalage using free induced modules.','Every semilinear B-module admits an embedding into and a surjection from induced semilinear modules, permitting dimension shifting in both Tate directions. Universal vanishing in any one degree is therefore equivalent to all-degree universal vanishing.','proof sketched','E','Serre1953Arithmetic§1 explicitly records the two shifts for finite-group cohomology, and MilneCFT II1/II3 gives the induced-module framework. The semilinear construction uses finite products/coproducts with the twisted B-action.',['Serre1953Arithmetic','MilneCFT'],['L31-group','S31-11.3'])
c(451,[464],[42],'1342–1350','Inertia order invertible gives trace surjective.','Let B be an integral normal commutative ring with finite G action and A=B^G local. If the inertia-group order at a maximal ideal of B is invertible in the corresponding residue field, then Tr_G(B) contains a unit of A, hence1. Every semilinear B-module is cohomologically trivial. The stated normal/integral setup is retained rather than discarded.','proof sketched','E','This is the tame trace argument: reduce modulo a maximal ideal, sum over the decomposition group, use the separable residue trace and the invertible inertia multiplicity, then lift a nonzero trace and use locality. The manuscript’s assertion is supported by this direct proof and the standard trace/projectivity theorem.',['AKO','MilneCFT'],['S31-11.3','S31-11.4','L31-group'],comp='CRT chooses an element supported at one maximal ideal; trace there equals |I| times the residue-field trace. Separability makes that field trace nonzero; |I| invertible preserves nonzeroness. The invariant trace lies outside the maximal ideal of A.')
c(452,[465],[43],'1352–1403','Relative trace of an endomorphism equals identity; restriction gives stable elements.','For H≤G finite and a G-module M with id_M=Tr_H^G(φ), φ∈End_H(M), M is relatively H-projective. Restriction on Tate cohomology is injective with image the H-stable elements, and unrestricted corestriction is surjective. Stable means the usual restriction/conjugation equalities on H∩gHg⁻¹.','proof sketched','B','Higman1954, as stated in AKO IV4.2, is the exact relative-projectivity criterion. The cohomological conclusion follows by the weighted transfer cor∘φ_* and the double-coset formula. It must be separated from the false extra claim about corestriction restricted to stable elements.',['AKO','HigmanBibliography','MilneCFT'],['S31-topics1.3','S31-3.3','S31-4.2','L31-group'],comp='Weighted transfer satisfies cor φ_* res=id. For a stable class a, the double-coset formula reduces res cor φ_*(a) to (Tr_H^G φ)_*(a)=a. Thus restriction identifies the stable subgroup; cor is onto since every class is cor(φ_*res(class)).')
c(453,[465],[43],'1384–1403','Corestriction is bijective on stable elements.','This extra assertion is false even for a faithful ring action satisfying relative trace-one. Let G=C4 act on B=Z^6 by σ=(12)(3456), H=<σ²>, and M=Z² via the first two coordinates. Then b=(1,0,1,0,1,0)∈B^H has b+σb=1. Tate H⁰(G,M)=F2 and the stable part of Tate H⁰(H,M)=F2² is diagonal F2, but cor on that diagonal is zero.','false as stated','C','Relative projectivity establishes CL-SA12-452, not bijectivity of ordinary corestriction on stable elements. The explicit counterexample satisfies faithfulness, normality of H, semilinearity and relative trace-one; the literature search found no theorem that rescues the stronger statement without an additional invertible-index condition.',['AKO','MilneCFT'],['S31-topics1.3','S31-11.3','L31-group'],comp='programs/check_calculations.py; outputs/calculations.json#relative_corestriction. On H-cohomology cor(a,b)=a+b mod2; on stable(a,a) it is0. Restriction sends the G-class to(a,a). Refined statement CL-SA12-452.')
c(454,[465],[43],'1404–1411','A relative version under assumptions on inertia.','The trace-one argument has a relative analogue when the inertia/decomposition data ensure a relative trace B^H→B^G containing1. Then each semilinear module satisfies the Higman condition. The compressed final condition on subgroup containment/conjugacy must be fixed from the ink before it is a complete ramification criterion.','open on the pages','C','AKO IV4.2 identifies exactly what relative trace-one proves. Tame local trace computations support special cases, but do not fill the manuscript’s unexpanded subgroup condition.',['AKO','MilneCFT'],['S31-11.4','L31-group'],confidence='medium')
c(455,[468],[44],'1417–1424','If Gi=1, H¹(G,O×)=0.','For a semilocal commutative ring O with finite G action, transitive on maximal ideals, and trivial inertia at a maximal ideal, the resulting Galois torsor O/O^G gives H¹(G,O×)=Pic(O^G)=0 because O^G is local. This uses the finite-group torsor criterion; it is a reconstruction of the short assertion.','stated without proof','E','Faithfully flat Galois descent and Picard triviality of local rings give the result once trivial inertia implies the torsor property. The arbitrary nontrivial-inertia comparison is a different claim and fails.',['SGA3IX','MilneCFT'],['S31-12.1','L31-group'],comp='A semilinear rank-one module descends under the torsor to an invertible O^G-module. Every invertible module over the local invariant ring is free, so its cocycle is a coboundary.',confidence='medium')
c(456,[468],[44],'1424–1433','Perhaps H¹(G,O×)→H¹(Gi,κ×) is an isomorphism.','False for the written semilocal hypotheses. Take O=F2[ε]/(ε³), G=C2 acting faithfully by ε↦ε+ε². There is one maximal ideal, Gi=G and κ=F2. Then H¹(G,O×)=C2, whereas H¹(Gi,κ×)=0.','open on the pages; false as stated','C','No normality, completeness or invertible-group-order hypothesis appears on this leaf. The finite local Artin counterexample therefore applies. Stronger descent/Hensel statements have extra hypotheses and do not establish this comparison.',['MilneCFT','AKO'],['S31-12.1','S31-12.2','L31-group'],comp='programs/check_calculations.py; outputs/calculations.json#semilocal_H1. O×=C4 generated by1+ε, σ acts by inversion; all four elements have norm1 and only two are coboundaries. Every displayed hypothesis is checked by exhaustive arithmetic. A valid tame replacement is CL-SA12-523.')
c(457,[469],[44,49],'1433–1437;1564–1581','Generalize this to GL_n.','An unconditional residual comparison H¹(G,GL_n(O))→H¹(Gi,GL_n(κ)) under the same semilocal assumptions is false already for n=1 by CL-SA12-456. Rank-n descent over a Galois torsor is a valid separate statement.','open on the pages','C','Nonabelian H¹ classifies semilinear forms, but residual reduction loses infinitesimal cocycles in wild characteristic. The vector-group descent passage on scan49 is connected to this language, not a proof of the proposed comparison.',['MilneAG2017','MilneCFT'],['S31-12.1','S31-12.2','L31-group'],comp='The n=1 special case is the saved Artin-ring counterexample. No inference for arbitrary n from a merely additive Hilbert90 calculation is used.')
c(458,[470],[44],'1438–1461','When can one pass to completion in Tate cohomology?','For A noetherian, G finite acting A-linearly on a finite A-module M, and I-adic completion, Tate cohomology commutes with completion: Hhat^r(G,M)⊗A Ahat≅Hhat^r(G,M⊗A Ahat), all r. The manuscript also proposes decomposition/inertia comparisons and dense-image variants whose full topology is unspecified.','open on the pages','C','Flatness of noetherian completion and a complete resolution with finite free terms give the stated sufficient condition. This settles a concrete version, not the entire undefined density assertion.',['EGAIII2','MilneCFT'],['S31-12.3','L31-formal','L31-group'],comp='In each Tate degree the complex has a finite direct sum of copies of M. Flat tensor commutes with kernels and images, hence cohomology. Finite generation identifies algebraic tensor with I-adic completion.',confidence='high')
c(459,[471],[45],'1463–1488','Idèles and the sign factor; pour tout? divided by units?','The entire draft is cancelled. In idèlic class field theory the image of the real sign group in an abelian quotient is the sign group modulo its intersection with the image/closure of global units. It need not inject unchanged. The displayed Z₂ may denote C2, not 2-adic integers.','withdrawn in the same text','E','MilneCFT V1 and VI3 describe ray-class/idèle quotients and the global-unit relation. The cancelled diagram is not a surviving theorem. Its exact target class field is not fully specified.',['MilneCFT'],['S31-12.4','L31-ideles'],comp='For a homomorphism S→J/K×U, the kernel is S∩(K×U); this yields the necessary quotient directly. No numerical class-group calculation is asserted.',confidence='medium')
c(460,[473],[45],'1489–1498','Norm units equal units iff unramified.','For a finite abelian extension L/K of nonarchimedean local fields with finite residue field, [U_K:N U_L]=e(L/K); hence N U_L=U_K iff unramified. The transcribed target U_L is wrong. Without the local-field scope the criterion fails: C((u))/C((t)), t=u², is ramified but has onto unit norm.','false as transcribed; true with reconstructed scope','E','Local reciprocity gives [K×:N L×]=[L:K], while valuations of norms have image fZ, so the unit index is e. MilneCFT I1 and III1.2 give the relevant norm facts. The source does not state the necessary finite-residue-field scope.',['MilneCFT'],['S31-11.4','S31-12.4','L31-ideles'],comp='programs/check_calculations.py; outputs/calculations.json#unit_norm. For C[[t]]× every unit has a square root b∈C[[t]]× and N_L/K(b)=b²; e=2.')
c(461,[475],[47,50],'1499–1517;1582–1594','Five vanishing conditions on groups, finite coefficients, tori and algebras.','The note attempts equivalences among high-degree vanishing for commutative affine algebraic groups, finite Galois modules, irreducible finite Fℓ-modules, tori, and multiplicative groups of finite separable algebras. One must keep n, perfectness and prime restrictions, and distinguish torsion-coefficient cd from unrestricted algebraic-group cohomology. Several displayed arrows/zeros are missing or cancelled.','proof sketched; not a complete five-way theorem','C','Finite-coefficient dévissage, Hilbert90, multiplicative-type structure and the Brauer criterion are established ingredients. The page’s complete five-way statement is not verified as written; the C2 determinant exception and degree1 correction affect its proposed proof.',['MilneAG2017','MilneCFT','Stacks03R8'],['S31-5.3','S31-13.1','L31-structure','L31-group'],confidence='medium')
c(462,[476],[47],'1517–1537','Reduce finite coefficients to irreducible Fℓ-modules.','If H^i(k,V)=0 for i>n and every irreducible finite continuous Fℓ-representation V of G_k, for all relevant primes ℓ, then the same holds for every finite torsion G_k-module. Conversely the implication is immediate.','proof sketched','E','Primary decomposition, filtration by ℓ-powers, a composition series over a finite quotient, and the long exact sequence prove the statement. MilneCFT II supplies continuous cohomology; this is classical dévissage.',['MilneCFT'],['S31-13.1','L31-group'],comp='Each finite continuous module factors through a finite group. Induct on composition length, then exponent, then direct-sum primary factors; no dimension shift at the upper vanishing boundary is required.')
c(463,[477],[47,48],'1533–1550','G is the product of unipotent and multiplicative factors over perfect k.','A commutative affine algebraic group over a perfect field has a unique product decomposition G=G_u×G_s with G_u unipotent and G_s of multiplicative type. It does not assert this product for imperfect fields or nonaffine groups such as abelian varieties.','stated without proof','A','MilneAG16.13 states precisely the perfect-field product and explains the general multiplicative subgroup/unipotent quotient. This is the classical structure used in SGA3, not a general Chevalley splitting.',['MilneAG2017','SGA3IX'],['S31-13.2','L31-structure'])
c(464,[478],[48,51],'1550–1563;1610–1621','H^i(U)→H^i(G) is an isomorphism for positive i; later i>1.','For an exact sequence 0→U→M→V→0 of discrete profinite-group modules with V a Q-vector space, H^i(U)→H^i(M) is an isomorphism for i≥2 and a surjection for i=1, with kernel V^G/im M^G. The scan48 degree1 claim is false; scan51 explicitly replaces the range by >1.','corrected by himself later: scans48 and51','E','Continuous cohomology of a discrete Q-vector space vanishes above0 by finite averaging. The long exact sequence gives exactly the corrected range. A quadratic cocycle over C(t) witnesses failure of injectivity at1.',['MilneCFT','Stacks03R8'],['S31-13.1','L31-group'],comp='programs/check_calculations.py; outputs/calculations.json#degree1_torsion_cocycle. U=μ∞⊂Ksep×; all roots of unity lie inK=C(t), so a quadratic character is nonzero inH¹(U), but g√t/√t is a coboundary inKsep×.')
c(465,[479],[48,49],'1558–1581','Cohomology commutes with the union of finite torsion parts.','For a profinite group acting continuously on discrete modules, continuous cohomology commutes with filtered colimits. In the written increasing union of finite torsion pieces, each continuous cochain has finite image and is contained in one piece.','proof sketched','E','MilneCFT II4 treats continuous cochains and passage to limits. Compactness of G^r and discreteness of the target prove the finite-image step, including compatibility of coboundaries.',['MilneCFT'],['S31-13.1','L31-group'],comp='A continuous map from compact G^r to a discrete target has finite image; filteredness places finitely many values in one stage. The same applies to a cochain witnessing that a class becomes a boundary.')
c(466,[480],[49],'1564–1581','In characteristic p an exponent-p unipotent group is a vector group; descent via GL_n.','Over a perfect field, a smooth connected commutative unipotent group killed by p is a vector group (Milne14.54). In characteristic0 commutative unipotent groups are vector groups. The smoothness/connectedness convention must be made explicit. A chosen additive-group isomorphism in characteristic p does not automatically provide GL_n-valued descent, since additive polynomial automorphisms need not be linear.','proof sketched with an unstated convention','A','MilneAG14.54 proves the exponent-p assertion through additive-polynomial modules;16.15 covers characteristic0. Finite infinitesimal groups such as α_p show why the smooth convention matters. The triangular automorphism gives a separate obstruction to the proposed linear descent argument.',['MilneAG2017'],['S31-13.2','L31-structure'],comp='programs/check_calculations.py; outputs/calculations.json#additive_automorphism. (x,y)↦(x+y^p,y) is additive with polynomial inverse (x,y)↦(x−y^p,y), but is not inGL₂. This does not refute the classification theorem.')
c(467,[482],[49],'1576–1581','The general case will be considered next.','The arbitrary-field continuation of the algebraic-group vanishing comparison is not present. Perfect-field decomposition/descent cannot simply be copied to the imperfect case.','open on the pages','C','MilneAG16.13 and16.20 precisely distinguish perfect-field products from imperfect-field extensions. No exact theorem matching every draft vanishing condition in the announced generality was identified.',['MilneAG2017','MilneADT'],['S31-5.3','S31-13.2','L31-structure'],confidence='medium')
c(468,[483],[50],'1582–1594','The regular-representation norm is1, with no exception.','For Γ=(Fℓ)^r, a nonzero element permutes the regular basis in ℓ^(r−1) cycles of lengthℓ, so its determinant is (−1)^((ℓ−1)ℓ^(r−1)). The unique failure of determinant1 is Γ=C2. Adding a one-dimensional inverse-determinant character repairs the norm-one embedding, changing its dimension.','false as stated','E','The determinant calculation is elementary representation theory. The norm-torus argument in the draft therefore needs the explicit C2 repair; a general reference to restriction of scalars cannot remove it.',['MilneAG2017','MilneCFT'],['S31-13.3','L31-structure'],comp='programs/check_calculations.py; outputs/calculations.json#regular_norm. Refined formula and repaired representation are recorded in CL-SA12-524.')
c(469,[486],[51],'1595–1609','Tsen’s theorem implies the needed cohomological bound.','A one-variable function field K over an algebraically closed field is C1. Every finite extension is also such a function field, so every finite extension has trivial Brauer group and cd(K)≤1 for finite torsion Galois coefficients.','proof sketched','E','Stacks03RD,03RC and03R8 give the exact chain Tsen→C1→Brauer vanishing on finite extensions→cohomological dimension≤1. The theorem predates the SGA notes; precise original publication metadata have not been checked here.',['Stacks03RD','Stacks03RC','Stacks03R8'],['S31-13.4','L31-field'])
c(470,[487],[51],'1599–1609','Hatted cohomology vanishes, with an uncertain field symbol.','The hatted group is not defined sufficiently to determine whether it means finite-group Tate cohomology, a modified Galois group or an ordinary positive-degree group. Ordinary H^i(K,Gm)=0 for i>0 follows in the stated Tsen setting; this does not identify all hatted degrees.','stated without proof; notation unresolved','F','Stacks03R8 settles ordinary positive-degree Gm cohomology under Brauer vanishing on every finite extension. MilneCFT II distinguishes Tate degree0 and negative degrees. The source’s hat and extension symbol remain scan questions.',['Stacks03R8','MilneCFT'],['S31-13.4','L31-field','L31-group'],confidence='low')
c(471,[491],[51],'1620–1623','The power exact sequence is written without multiplicative stars.','For n invertible in K and Ksep a separable closure, 1→μ_n→Ksep× --n→ Ksep×→1 is exact. Identifying μ_n with Z/n requires a choice and Galois invariance of the appropriate roots. The additive group is not the intended middle term.','stated without proof','E','Kummer theory in MilneCFT and the finite-coefficient/Brauer argument in Stacks03R8 support the corrected multiplicative sequence. The missing stars are retained as readings to check.',['MilneCFT','Stacks03R8'],['S31-13.4','L31-field'])
c(472,[492],[51],'1623–1626','For p=char K use the additive group.','The exact Artin–Schreier sequence 0→Fp→Ksep --(F−1)→Ksep→0 and additive Galois acyclicity give H^i(K,Fp)=0 for i>1. The final line does not prove arbitrary flat-sheaf acyclicity.','proof sketched','E','Stacks0A3J/0A3K and SGA4 X5.1 state the result. The characteristic-p step is independent of the prime-to-p Kummer sequence.',['Stacks0A3J','Stacks0A3K','SGA4III'],['S31-13.4','L31-field'])

c(473,[],[52],'6–27','A transcendence-degree-one extension adds at most1.','If every finite extension k′/k has H^i(k′,Γ)=0 for i>n and all finite constant abelian Γ, then a finitely generated extension K/k of transcendence degree1 has the corresponding vanishing for i>n+1. In particular a function field of transcendence degree d over an algebraically closed field has torsion Galois cohomological dimension≤d.','proof sketched','A','SGA4 X2.1 proves the prime-to-characteristic extension bound; X5.1 handles characteristic-p coefficients. The written Hochschild–Serre argument also needs finite-coefficient dévissage to apply the constant-coefficient hypothesis to H^j of the geometric Galois group.',['SGA4III','Stacks03R8','MilneCFT'],['L31-field','S31-13.4'],comp='The geometric kernel has cohomology only in degrees0,1 by Tsen; the base has none above n after dévissage. Thus every nonzero E₂^(i,j) has i+j≤n+1.',source='K31-01')
c(474,[],[55,56],'46–86','Even for injective F, sections on a closed Y need not extend to a neighborhood.','For irreducible X with distinct closed points a,b, let F=∏_(x∈X)i_(x)*Q, the injective sheaf of arbitrary Q-valued functions. The section of F|{a,b} whose germs are0 at a and1 at b has no extension to any neighborhood. A closed pushforward from an irreducible curve meeting a line at two points gives the same phenomenon with irreducible Y.','proved there','C','The counterexample is valid; the exact historical publication of this construction was not identified by the searches on closed inverse-image of injectives. Stacks03F9 supplies the relevant acyclicity framework but does not identify closed restriction with a cohomology-preserving operation.',['Stacks03F9','SGA4V'],['S31-6.2','S31-8.2','S31-16.1'],comp='Each i_(x)*Q is injective since stalk is exact and Q is injective; products remain injective. An extension would be0 and1 on two nonempty open subsets, which intersect by irreducibility. This re-proves the contradiction, not just its summary.',source='K31-01')
c(475,[],[56,57,58,59],'92–159','Two irreducible curves meeting twice give nonzero H¹ after closed restriction.','Let X be irreducible, Y=Y₁∪Y₂ with irreducible curves meeting in two distinct closed points a,b, and F the injective sheaf of arbitrary Q-valued functions on X. The class of(0,1) in F_a×F_b is not the difference of sections on Y₁,Y₂. The closed-cover exact sequence therefore gives H¹(Y,F|Y)≠0.','proof sketched with crossed and mismatched indices','C','The argument checks after keeping φ_i and φ′_i paired correctly. Its exact historical location was not found; this is an explicit counterexample to the opening question, not a consequence of injective acyclicity on X.',['SGA4V','Stacks03AZ'],['S31-6.2','S31-8.2','S31-16.1'],comp='If φ₂−φ₁=0 near a and φ′₂−φ′₁=1 near b, restrictions of a hypothetical pair of sections force φ₁=φ′₁ on a nonempty ambient open W₁ and φ₂=φ′₂ on another W₂. Their intersection is nonempty, yielding0=1. The raw formula at155 has φ′₂ where this proof requires φ′₁; listed for ink check.',source='K31-01')
c(476,[],[59],'162–174','An irreducible surface Y in a threefold gives the same failure.','There exist irreducible closed Y of dimension2 in irreducible X of dimension3 and an injective sheaf F on X with H¹(Y,F|Y)≠0. Reconstruct explicitly over Q: X=A³, Y=V(z), X₁=V(z−y(y−x²+1)). Then X₁≅A² and X₁∩Y is the union of y=0 and y=x²−1, meeting at(±1,0). Push forward the preceding injective sheaf from X₁.','construction sketched','C','The written geometric construction is valid; the explicit equations are this run’s reconstruction. Exact historical identification remains unlocated after the closed-restriction searches.',['SGA4V','Stacks03AZ'],['S31-16.1','S31-6.2'],comp='Closed pushforward preserves injectives because its left adjoint inverse-image is exact; restriction to Y is the closed pushforward from X₁∩Y. Closed pushforward is exact, so its H¹ equals the nonzero H¹ of CL-SA12-475. Equation/intersection certificate in outputs/calculations.json#closed_restriction.',source='K31-01')
c(477,[],[60,62],'179–219;270–282','Vanishing H¹ on every open is equivalent to vanishing of all higher groups there.','For an abelian sheaf F on any topological space X, H¹(U,F)=0 for every open U iff H^i(U,F)=0 for every open U and all i>0. These imply and are implied by vanishing of positive Čech cohomology for every open cover of every U.','proved there','E','The argument is the ordinary-space Cartan acyclicity criterion; SGA4 V4.3/V5.9 and Stacks03F9 give the general framework. The source’s cokernel-flasque argument supplies a direct re-proof of the H¹ criterion.',['SGA4V','Stacks03F9','Stacks03AZ'],['S31-6.1','S31-6.3','L31-cech'],comp='Embed F→I injective. H¹(U,F)=0 makes0→F(U)→I(U)→C(U)→0 exact for every U. Flasqueness of I then makes C flasque, so the two-term flasque resolution gives vanishing in every positive degree.',source='K31-01')
c(478,[],[60],'188–219','For X noetherian it suffices to check pairs of opens.','For noetherian topological X, the preceding conditions are equivalent to surjectivity F(U)⊕F(V)→F(U∩V) for every pair of opens. Noetherianity is used to choose a maximal open on which a locally trivial H¹-class vanishes, or to reduce to a finite cover.','proof sketched; last sentence interrupted','E','The finite-cover gluing argument is standard Čech theory and is supported by SGA4 V/Stacks03F9. The inserted noetherian hypothesis must not be dropped merely because the other implications hold on arbitrary spaces.',['SGA4V','Stacks03F9'],['S31-6.1','L31-cech'],comp='A nonzero H¹-class is locally zero. If zero on U and V, Mayer–Vietoris plus the assumed surjectivity makes it zero on U∪V. Noetherian quasi-compactness gives a finite such cover of any open.',source='K31-01')
c(479,[],[61],'224–265','Vanishing δ(L/K,k/l) for every finite or finitely generated L/K iff k⊂l(K^p).','For fields l⊂k⊂K of characteristic p, the leaf proposes an admissibility criterion involving a defect δ and modules N with subscripts L/K/k and L/K/l. These objects are not defined in the supplied passage. The example adjoining x with x^p∈k outside l(K^p) suggests a kernel-of-differentials obstruction.','stated without proof; definitions missing','F','The transitivity sequence for Kähler differentials explains the visible map Ω¹_(K/k)⊗L→Ω¹_(L/k), but does not identify δ or establish its claimed universal criterion. The p-basis/differentials searches found no exact match.',['StacksDifferentials'],['S31-14.4','S31-16.2'],comp='For a simple purely inseparable extension L=K(x), x^p=a, differentiating the defining relation over l gives da=0 inΩ¹_(L/l). Whether the resulting kernel is the author’s N is explicitly unresolved.',source='K31-01',confidence='low')
c(480,[],[65],'298–315','Every noetherian ℓ-sheaf has elementary composition factors.','A constructible ℓ-primary torsion sheaf on a noetherian scheme admits a finite filtration by sheaves supported on locally closed integral strata, locally constant on a sufficiently small open, with generic finite Galois-module data. The adjective strictly elementary and the required unibranch refinement use the finite-cover variant in the subsequent lines.','stated without proof','A','SGA4 IX2.9 and IX5.5 provide constructible dévissage and reduction by finite maps. The exact generic-direct-image-with-extension-by-zero notation is reconstructed; the phrase G finite on X in line310 conflicts with its domain Spec k(x).',['SGA4III'],['S31-16.3','L31-devissage'],source='K31-01',confidence='medium')
c(481,[],[65],'317–348','cdℓ≤n iff the generic direct-image tests a),b) hold.','For every integral closed Y⊂X, generic i:η→Y and finite ℓ-primary G on η, require H^(n+1)(Y,i_*G)=0 and surjectivity H^n(Y,i_*G)→H^n(Z,(i_*G)|Z) for every closed Z⊂Y. Through the elementary dévissage these test cdℓX≤n; the finite unibranch variant is kept distinct.','proof sketched','A','SGA4 IX5 and X4.1 implement this generic-direct-image/noetherian-induction mechanism. The cancelled supports analogue is not included as a proved extension.',['SGA4III'],['S31-16.3','L31-devissage'],comp='The exact sequence0→j!j* i_*G→i_*G→i_Z*(i_*G|Z)→0 converts a),b) into H^(n+1) vanishing for elementary factors; dévissage and dimension shifting finish the cd test.',source='K31-01',confidence='medium')
c(482,[],[66,67,68],'353–472','A strictly increasing φ reduces the dimension bound to generic direct images.','On noetherian X, let φ decrease strictly under proper specialization. If cdℓk(x)≤φ(x) and for y∈closure{x},y≠x, cdℓFrac(O^sh_(closure{x},y))<φ(x)−φ(y), then H^i(X,F)=0 for i>sup_(F_x≠0)φ(x) for every ℓ-primary torsion sheaf F.','proof sketched','A','Exact published theorem SGA4 X4.1. The strict inequality, exclusion y=x and total-fraction-ring interpretation match the source. The preceding generic tests explain the induction.',['SGA4III'],['S31-16.3','L31-devissage'],source='K31-01')
c(483,[],[68],'442–472','Stalk cohomology gives the spectral vanishing region.','For g:η→X and q>0, (R^qg_*G)_y=H^q(Frac O^sh_(X,y),G). Under CL-SA12-482, φ(R^qg_*G)<φ(η)−q. Thus E₂^(p,q)=0 when p+q≥φ(η),q>0; the written p−q is incompatible with this derivation.','proof sketched; displayed sign false as transcribed','A','SGA4 X4.1 proof explicitly uses the same support and spectral bound. The corrected plus sign is an ink-check proposal, not a silent diplomatic correction.',['SGA4III','Stacks03AZ'],['S31-16.3','L31-devissage'],comp='programs/check_calculations.py; outputs/calculations.json#spectral_degrees. If p≤φ(support)<φ(η)−q then p+q<φ(η). Incoming differentials at the bottom row have total degree one less than the target.',source='K31-01')
c(484,[],[69],'477–483','φ(x)≤φ(y)+2 trdeg k(x)/k(y).','For a finite-type morphism of locally noetherian schemes, the claimed fieldwise inequality depends on the particular φ intended. It does not follow for an arbitrary function satisfying the previous sufficient conditions: such a function can be increased independently on a source component.','stated without proof; definition not explicit','F','SGA4 X2.1 gives the actual field cd inequality; ILO XIV2.5.2 defines the induced dimension function δ_X=δ_Y∘f+trdeg. Neither identifies the draft’s unspecified φ automatically. Scan70 supplies another φ candidate, which must be compared before assigning a precise theorem.',['SGA4III','ILO2014'],['S31-15.3','L31-devissage'],source='K31-01',confidence='low')
c(485,[],[70],'3–24','The strict-local fraction-field bound is probably always true for good X.','For a strictly henselian noetherian integral local ring R and ℓ invertible in R, cdℓFracR=dimR. For reducible closed subschemes use the supremum over total-fraction components.','open on the pages','B','ILO XVIII-B4.1.2 proves the upper bound for every such integral R, with no quasi-excellence requirement. SGA4 X2.4–2.5 gives the reverse bound. This fully settles the clean invertible-prime fraction-field question, stronger than the source’s undefined good hypothesis.',['ILO2014','SGA4III'],['S31-topics2.1','S31-4.3','S31-15.3','L31-field'],source='K31-02',date='SGA4 X3 conjecture printed1973; ILO seminar2006–08, arXiv first2012-07-16, Astérisque363–364 publication2014. Exact first announcement of the full noetherian theorem not established.')
c(486,[],[70],'29','Does a henselian local domain satisfy cdℓK≥dimA+cdℓk?','The margin asks the lower bound for a noetherian henselian integral local ring with finite residue-field cdℓ. With ℓ invertible and ℓ≠2 or all residue fields nonorderable, SGA4 X2.4 proves it even without henselianity. The line alone does not impose all these restrictions.','open on the pages','A','The precise published lower bound is established in SGA4 X2.4. A statement including noninvertible ℓ or silently removing the real exception is not justified by that theorem.',['SGA4III','ILO2014'],['S31-9.2','L31-field'],source='K31-02')
c(487,[],[70,71],'10–26;105–115','Global cd follows from a φ supremum and local spectral estimates.','Under the strict-local fraction-field bounds, the function φ(x)=sup_(y∈closure{x})(cdℓk(y)+2dimO_(closure{x},y)) satisfies the needed specialization inequalities, yielding cdℓX≤φ(X). The scan71 generic-point lemma is the same induction expressed as support plus fraction-field bounds.','proof sketched','A','SGA4 X4.1–4.4 gives the precise global criteria and standard finite-type consequences. Combining it with ILO XVIII-B4.1.2 removes the old unproved local input for invertible ℓ. The alternate pencilled φ is not substituted without proof.',['SGA4III','ILO2014'],['L31-devissage','S31-15.3'],comp='For strict specialization x→y, chain concatenation gives dimO_(closure{x},z)≥dimO_(closure{x},y)+dimO_(closure{y},z); hence φ(x)≥φ(y)+2c with c≥1. Since cdℓFracO^sh≤c, the required strict gap follows.',source='K31-02')
c(488,[],[72],'120–154','Multiplicative-type monomorphisms into affine groups are closed and have affine quotients.','If G is of multiplicative type and u:G→H is a monomorphism of S-group schemes with H affine, then u is a closed immersion, H/G is represented by an affine S-scheme, and H→H/G is a G-torsor for the fpqc topology. The preceding free-action theorem supplies the graph closedness and finite-type/presentation descent.','proof sketched on reused typescript','A','Exact match SGA3 IX2.3–2.5. The diagonalizable case and effective fpqc descent of affine schemes are explicitly cited in the supplied page and in print.',['SGA3IX'],['S31-7.1','L31-rigidity'],source='K31-02')
c(489,[],[74],'157–166','Theorem1_n: codimension support gives H^i(A[t],F)=0 above n+1−m.','For strictly local noetherian A of dimension n satisfying the intended good finiteness condition, ℓ invertible, and an ℓ-primary sheaf F on SpecA[t] vanishing in codimension<m, the claimed bound is i>n+1−m. A precise established version assumes A quasi-excellent and uses the induced dimension function; the question about removing torsion is separate.','proof sketched; hypotheses and torsion necessity questioned','B','SGA4 XIV3–4 proves the finite-type-over-field/trait versions. ILO XV1.1.1/1.2.1 gives the quasi-excellent generalization, with constructible bounded torsion coefficients and then filtered limits. No general arbitrary-coefficient theorem is claimed.',['SGA4III','ILO2014'],['S31-topics2.3','S31-15.3','L31-affine'],source='K31-02')
c(490,[],[74],'168–172','Theorem2_n: cdℓD(f)≤n for strict-local A.','For quasi-excellent strictly henselian noetherian A of dimension n and ℓ invertible, every affine open U⊂SpecA has cdℓU≤n. Without quasi-excellence the displayed all-noetherian statement is false: ILO constructs regular strictly local dimension-d examples with cdℓD(f)=2d−1.','stated without proof at first; later proof attempted','B','ILO XV1.2.2 is the precise affirmative theorem, equivalent to the affine Lefschetz statement. XVIII-B3.2.5 gives counterexamples without excellence. The separate fraction-field statement CL-SA12-485 remains true for every noetherian ring.',['ILO2014','SGA4III'],['S31-topics2.1','S31-topics2.3','S31-15.3','L31-affine'],source='K31-02',date='Finite-type-over-trait case attributed to Gabber1994 by ILO XV1.1.2; general exposition arXiv2012, publication2014. Exact first circulation of the counterexamples not established.')
c(491,[],[74,75],'172–222','2′_(n+1) implies1_n, with low-dimensional exceptions checked.','The reduction embeds D(f) as the closed locus tf−1=0 in A[t], and conversely compactifies a closed integral support S⊂A¹_A in P¹_A. Proper base change and local cohomology at the infinity section reduce the affine-line bound to principal-open bounds in strict local rings; dimensions0 and1 need separate treatment.','proof sketched','A','SGA4 XIV4.3–4.4 gives these reductions. Its edited note warns about the dependency order, agreeing with the draft’s need to arrange the induction; this is not a proof from an unestablished 1_n alone.',['SGA4III'],['L31-affine','S31-16.4'],comp='The graph equation tf−1 is a nonzerodivisor, so D(f) has codimension at least1 in A[t]. In the reverse direction dim local closure≤n+1−m; the proper special fiber has dimension≤1 and cohomology only through degree2.',source='K31-02')
c(492,[],[76,77,78,79,80],'225–382','1′_n+2′_(n+1)⇒2′_(n+2), then affine space, then a one-dimensional base.','In the essentially finite-type setting over a field, the simultaneous induction projects an affine space by one coordinate and uses R^qf_*F supported in codimension≥q−1. The same proof is extended toward a base of dimension≤1. The scan80 local-support calculation is one degree short until the local principal-open input is correctly indexed.','proof sketched; an index doubt is marked','A','SGA4 XIV4.5 supplies a completed induction over a field or a one-dimensional base. The manuscript’s separate crossed first implication and its unit discrepancy remain documentary evidence of an unfinished proof arrangement.',['SGA4III'],['L31-affine','S31-16.4'],comp='If support codimension of R^q is at least q−1 and base dimension is n+1, then p≤n+1−(q−1), hence p+q≤n+2. For local support H_Z^q the identification with H^(q−1) of the complement requires q≥2; q=0,1 are handled separately.',source='K31-02')
c(493,[],[80],'385–402','For affine finite-type X over strict-local A, cd≤max(dimX₀,dimX′+1).','For an affine finite-type morphism X→SpecA with A strictly local quasi-excellent and ℓ invertible, the affine Lefschetz bound is cdℓX≤sup_x(dim closure{f(x)}+trdegκ(x)/κ(f(x))). In the catenary dimension setup this is the displayed max(dimX₀,dimX′+1); for integral dominant X it is bounded by dimA plus generic-fiber dimension.','open on the pages, with finite-type special case labelled proved','B','ILO XV1.2.1 gives the exact dimension-function formulation; SGA4 XIV3–4 gives the earlier special cases. The raw good-ring condition is replaced explicitly, and the numerical max formula is identified through the usual dimension formula rather than asserted over every nonexcellent base.',['ILO2014','SGA4III'],['S31-15.3','L31-affine'],source='K31-02',confidence='medium')
c(494,[],[80],'403–409','Without affineness replace dimensions by twice dimensions.','The note proposes cdℓX≤max(2dimX₀,2dimX′+1), and for integral dominant X over a positive-dimensional strict-local base a bound2dimA−1+2d, where d is generic-fiber dimension. A precise modern generalization requires the chosen dimension function and base conditions.','open on the pages','C','SGA4 X4 gives the familiar2dim+field-cd bounds; ILO XVIII-A gives general local2d−1 bounds. These establish related precise cases, but this run did not identify a source proving every quantifier of the draft’s nonaffine max formula.',['SGA4III','ILO2014','ILOXVIIIA'],['S31-15.3','L31-affine'],source='K31-02',confidence='medium')
c(495,[],[81],'410–446','Induct on ambient affine-space dimension; is the exceptional codimension possible? non.','The leaf sketches cdℓX≤n+r−codim(X,A^r_A), checks r=0,1, and ends by invoking the spectral sequence for projection A^r_A→A^(r−1)_A. The margin rejects a proposed exceptional dimension configuration. This is a sketch, not a finished proof in the manuscript.','proof sketched; final induction unwritten','A','The support-dimension induction is completed in SGA4 XIV and generalized by ILO XV. The displayed subtraction/sign at the r=0 case must be read as a dimension inequality, and the vague good-Jacobson qualification is not a theorem hypothesis by itself.',['SGA4III','ILO2014'],['L31-affine','S31-16.4'],source='K31-02')
c(496,[],[82],'447–463','An affine pointwise bound, then a claimed integer-ring counterexample.','The all-noetherian proposed bound cdℓX≤sup_x(cdℓκ(x)+dimO_(X,x)), with ℓ invertible, is false. The source’s full integer-ring example does not satisfy ℓ invertible. A valid later counterexample comes from ILO XVIII-B3.2.5: U=D(f) in a regular strict-local d-dimensional R has cdℓU=2d−1, while every pointwise term is≤d by cdℓFracR=d and SGA4 X2.4.','open on the pages; author rejects it using an example outside the displayed hypotheses','B','The manuscript’s own refutation is invalid for the fixed invertible prime, but the statement in unrestricted noetherian generality is genuinely refuted by the later nonexcellent examples. This is a new deduction from the opened results, not an assertion found verbatim in either source.',['ILO2014','SGA4III'],['S31-15.3','S31-4.3','L31-affine'],comp='Choose d≥2. For y∈U, O_(U,y)=R_y and FracR_y=K. SGA4 X2.4 gives cdℓκ(y)+dimR_y≤cdℓK=d. Hence the supremum≤d<2d−1=cdℓU. For ℓ=2, strict locality and2 invertible give sqrt(−1)∈R, so the real-exception hypothesis is checked.',source='K31-02')
c(497,[],[83],'464–512','Affine finite-type X/Z has cdℓX≤dimX+1.','Let X be affine of finite type over Z, ℓ invertible on X, and either ℓ odd or the characteristic-zero part lie over a totally imaginary number field. Then cdℓX≤dimX+1. The relative dimension d case has bounds q≤d generically, q≤d+1 on closed fibers, leading to p+q≤d+2.','proof sketched','A','SGA4 XIV3.1 and X6, with the field cohomological-dimension bounds, give the arithmetic affine consequence. The source’s primed cd′ notation is not silently identified with the flat-site dimension from scan3.',['SGA4III','ILO2014'],['S31-15.3','L31-affine','L31-field'],comp='For q=d+1, support lies at closed points so p≤1. For q≤d, base cohomological dimension≤2 gives p≤2. Both regions satisfy p+q≤d+2=dimX+1.',source='K31-02')
c(498,[],[84],'513–534','Hochschild cohomology of a multiplicative-type group vanishes in positive degree.','For affine S, multiplicative-type S-group H and a quasi-coherent H-module F, H^i_Hochschild(H,F)=0 for i>0. Reduce fpqc-locally to a diagonalizable group, where invariants are the degree-zero summand of a grading and are exact.','proof sketched on a globally cancelled reused page','A','Exact SGA3 IX3.1. Global pencil cancellation does not mean the theorem was mathematically retracted; it is retained in print. The source’s missing inequality after i is restored only in the modern statement.',['SGA3IX'],['S31-7.4','L31-rigidity'],comp='Flat base change commutes with the explicit cochain complex and its cohomology. Faithful flatness detects vanishing; the diagonalizable case is exactness of the graded degree-zero functor.',source='K31-02')
c(499,[],[84],'536–546','Two homomorphisms equal modulo a square-zero ideal are conjugate by g≡e.','Let S affine, S₀ defined by J²=0, H of multiplicative type, G an S-group scheme, and u,v:H→G agree over S₀. Then v=Int(g)u for some g∈G(S) reducing to identity.','stated with references on a globally cancelled reused page','A','Exact SGA3 IX3.2. The infinitesimal difference is a Hochschild1-cocycle, killed by IX3.1; the reference to SGA3 III supplies the deformation interpretation.',['SGA3IX'],['S31-7.4','L31-rigidity'],source='K31-02')
c(500,[],[85],'547–560','For a good integral affine X, cdℓX≤cdℓK; equality on small opens?','The page conjectures cdℓX≤cdℓFracX for an integral affine good scheme with ℓ invertible, and eventual equality on sufficiently small opens. For finite-type schemes over fields, and standard arithmetic cases, affine Lefschetz and field dimension formulas establish the upper bound. The word good and the uniform small-open quantifier are not defined.','open on the pages','C','SGA4 XIV and ILO XV establish precise finite-type/quasi-excellent dimension-function bounds. ILO XVIII-B shows that an arbitrary noetherian replacement is false. No opened reference in this search established the exact full good-scheme conjecture or stabilization on all sufficiently small opens.',['SGA4III','ILO2014'],['S31-topics1.1','S31-topics2.1','S31-15.3','L31-affine'],source='K31-02',confidence='medium')
c(501,[],[85],'560–582','Mixed characteristic: max(cdℓK,δ(Vℓ)+3), followed by a stronger surviving claim.','When ℓ is neither invertible nor nilpotent, the draft proposes cdℓX≤max(cdℓK,δ(Vℓ)+3), where ℓ^δ(k)=[k:k^ℓ]. It deletes a +1 replacement and finally asserts cdℓX≤cdℓK when another prime is inverted. These are distinct surviving/cancelled formulations.','open on the pages; intermediate stronger formula withdrawn','C','SGA4 X3 explicitly flags the mixed-characteristic p-rank difficulty. Gabber–Orgogozo’s work on p-cohomological dimension, referenced by ILO, is relevant, but its field theorem is not an exact proof of all these affine-scheme inequalities. The +3 constant and final extra-prime hypothesis remain unmatched.',['SGA4III','ILO2014','GabberOrgogozo2008'],['S31-17.1','S31-17.2','L31-affine'],source='K31-02',confidence='medium')
c(502,[],[85],'584–592','Henselian mixed-characteristic affine opens have bound dimA+δ(k)+cdℓk.','For a good noetherian henselian local domain A of characteristic-zero fraction field, residue characteristicℓ and finite p-rank δ(k), the page conjectures cdℓU≤dimA+δ(k)+cdℓk for every affine open U. The exact coefficient dimension atℓ must be retained.','open on the pages','C','Gabber–Orgogozo2008 proves a refined p-cohomological-dimension theorem for fraction fields of excellent henselian local domains; it is close but does not by itself identify every affine-open assertion in this leaf. Quasi-excellent prime-to-characteristic affine Lefschetz does not cover ℓ equal to the residue characteristic.',['GabberOrgogozo2008','SGA4III','ILO2014'],['S31-17.1','S31-17.2'],source='K31-02',confidence='medium')
c(503,[],[86],'593–616','Fiberwise schematic density implies schematic density for a flat family.','Let X→S be flat and U⊂X open, with U_s schematically dense in X_s for every s. If X is locally noetherian, or if X→S is locally finitely presented and U is retrocompact in X, then U is schematically dense in X.','proof sketched on a globally cancelled reused page; ending cut off','A','Exact SGA3 IX4.6, using IX4.3–4.4 and noetherian approximation. The assumptions are alternatives; local finite presentation alone does not replace the retrocompactness requirement in this proof.',['SGA3IX'],['S31-7.3','L31-density'],source='K31-02')

c(504,[],[87],'4–6','For good henselian local rings of residue characteristic zero, everything is verified thanks to Artin.','This is an announcement referring to the preceding dimension programme, not a self-contained theorem. In the excellent henselian characteristic-zero setting, the affine Lefschetz and local dimension assertions have the expected prime-to-characteristic bounds; the phrase everything cannot fix which of the earlier variants was intended.','stated without proof','A','SGA4 X and XIV record the precise Artin results, while ILO XV extends the excellent-base affine theorem. The announcement is matched to these precise theorems rather than expanded into a claim that every scan85 variant follows.',['SGA4III','ILO2014'],['L31-affine','S31-15.3'],source='K31-03',confidence='medium')
c(505,[],[88],'11–25','Equality on all n-torsion subgroups forces equality of homomorphisms or subgroups.','For finite-type multiplicative-type group schemes, the union of the n-torsion subgroup schemes is universally schematically dense. Two morphisms agreeing on all such subgroups coincide; a subgroup containing all of them is the whole group, under the immersed-subgroup convention of the text.','proof sketched on globally cancelled reused typescript','A','SGA3 IX4.7 and its corollaries establish schematic density and the equality tests. The truncated last remark about a single integer m is not treated as a completed cofinal-torsion criterion.',['SGA3IX'],['S31-7.3','L31-density'],source='K31-03')
c(506,[],[90],'30–59','The Gysin map is surjective for i≥n+1 and bijective for i≥n+2.','Let X be regular projective of pure dimension n over a separably closed field, Y a regular hyperplane section, and F a locally constant torsion sheaf with orders invertible in the field. Purity and affine Lefschetz make H^(i−2)(Y,F(−1))→H^i(X,F) surjective for i≥n+1 and an isomorphism for i≥n+2. The deleted invertibility condition is necessary for this argument.','proof sketched','A','SGA4 XIV3.3 is the exact Gysin consequence; relative purity is treated in XVI3.7. The two boundary degrees follow from the localization sequence, not from a convention about the ambiguous H_Y exponent.',['SGA4III'],['S31-18.1','L31-affine','L31-comparison'],comp='For U=X−Y, H^j(U,F)=0 for j>n. In H^(i−1)(U,F)→H_Y^i(X,F)→H^i(X,F)→H^i(U,F), the last term vanishes for i≥n+1, and the first also vanishes for i≥n+2.',source='K31-03')
c(507,[],[90,91],'61–76','H^(2n)(X,μ_N^⊗n)=Z/N.','For connected regular projective pure n-dimensional X over a separably closed field and N invertible, the trace identifies H^(2n)(X,μ_N^⊗n) with Z/N. The draft inducts through a regular hyperplane section; existence and connectedness of a suitable section are required inputs.','proof sketched','A','SGA4 XVIII trace/duality supplies the canonical formulation; the Gysin argument of XIV3.3 supplies the inductive degree step. The retained projectivity and base-field setup must not be dropped when quoting the short corollary.',['SGA4III'],['S31-18.1','L31-comparison'],comp='For n≥2,2n≥n+2, so the preceding Gysin map is an isomorphism; the twist drops from n to n−1. Dimensions0 and1 are separately invoked by the manuscript.',source='K31-03')
c(508,[],[91],'80–87','Moyennant dualité: restriction injective through n−1, bijective through n−2.','In CL-SA12-506’s setup, étale weak Lefschetz says H^j(X,F)→H^j(Y,F|Y) is injective for j≤n−1 and bijective for j≤n−2, for finite locally constant invertible torsion coefficients; extend appropriate bounded torsion coefficients by limits.','proof sketched conditional on duality','A','SGA4 XIV3.3 and XVIII duality establish the stated range. The condition Moyennant dualité is a dependency, not evidence that duality was proved on this leaf.',['SGA4III'],['S31-18.1','L31-comparison'],comp='Duality pairs H^j(X,F) with the dual-coefficient group in degree2n−j. Surjectivity at2n−j≥n+1 dualizes to injectivity at j≤n−1; bijectivity at2n−j≥n+2 gives j≤n−2.',source='K31-03')
c(509,[],[93,94],'101–178','A finite normal extension split on the punctured divisor is étale.','A precise published version: A excellent normal local domain,0≠t∈radA,dimA≥3, and B a finite normal integral A-algebra containing A, with B/tB completely split over Spec(A/tA) away from its closed point; then B/A is étale. The draft instead uses a quotient-of-regular/chain condition and normal t-adic completion; these are explicit technical alternatives, not A/tA regularity.','proof sketched; formal algebraization and chain hypotheses invoked','A','Exact SGA4 XV3.3; remark3.4 records the weaker technical hypotheses used in the proof. The published proof follows the same punctured-neighborhood algebraization, using depth≥2 and universal catenarity. The marginal extension from split to an extendible étale cover is a descent variant.',['SGA4III','SGA2'],['S31-18.2','L31-comparison'],comp='The nonétale locus meets V(t) only at the closed point, hence has dimension≤1. Universal catenarity and dimA≥3 make its codimension≥2 in A and B; normality then identifies B with sections over the étale locus. Formal extension and SGA2 algebraization finish the quoted proof.',source='K31-03')
c(510,[],[95,96],'183–223','A prime-to-residue-characteristic cover of a smooth curve, generically split on a section, is étale along the section.','Let X→Y be smooth of relative dimension1, Y normal integral with the stated noetherian/excellence qualification, and X′/X a finite normal Galois cover of invertible group order. Assume it is étale on the generic fiber and completely split at the generic point of a section g:Y→X. Then it is étale along g(Y). A rational point gives complete splitting for the Galois cover.','proof sketched','A','SGA4 XV3.1–3.3 proves the corresponding tame extension mechanism, using Abhyankar and purity; XV2.1 is the smooth-local consequence. The manuscript’s removal of the quotient-of-regular assumption is justified there by approximation to excellent finite-type rings, not by simply deleting all finiteness hypotheses.',['SGA4III','SGA1'],['S31-18.2','L31-comparison'],source='K31-03',confidence='medium')
c(511,[],[96,97],'225–265','The two-dimensional tame local lemma, with Abhyankar to be made explicit.','Let A be regular local of dimension2 with regular parameters x,y. A finite normal Galois extension B/A of group order invertible in A, branched only in V(x) and completely split at the generic point of V(y), is étale. After strict henselization and choosing a connected component, tame Abhyankar gives B=A[T]/(T^n−x); splitting modulo y forces n=1.','proof sketched; external lemma explicitly requested','A','SGA1 X3.6 is the named Abhyankar lemma, and SGA4 XV3 uses it in this smooth-acyclicity proof. The coordinate form requires strict locality and a connected normal component; it is not asserted before those reductions.',['SGA1','SGA4III'],['S31-18.2','L31-comparison'],comp='In A/yA, x is a uniformizer. T^n−x is Eisenstein, hence defines a degree-n field extension of its fraction field. Complete splitting at that generic point is possible only when n=1.',source='K31-03')
c(512,[],[97,98],'270–283','A smooth morphism is locally1-aspherical for prime-to-residue-characteristic groups.','Every smooth morphism X→Y is locally acyclic and locally1-aspherical for the set of primes invertible on Y. The nonabelian degree1 part concerns finite groups of those orders.','proof sketched; manuscript stops after reduction to relative curves','A','Exact SGA4 XV2.1, with proof reducing to henselized affine lines and the tame-cover lemma2.6. The source states only the1-aspherical conclusion; the published theorem also contains abelian local acyclicity.',['SGA4III'],['S31-18.2','L31-comparison'],source='K31-03')
c(513,[],[98],'290–301','Smooth base change; invariance under extensions of separably closed fields.','For qcqs f, higher direct images of invertible torsion étale coefficients commute with smooth base change under the precise SGA4 XVI1.1–1.2 hypotheses. For X qcqs over a separably closed field and an extension of separably closed fields, cohomology with prime-to-characteristic torsion coefficients is invariant. The page omits some ambient hypotheses in its compressed application.','stated without proof','A','SGA4 XVI1.1–1.2 and1.5–1.6 give the exact statements. Arbitrary nonquasicompact X and arbitrary coefficients are not silently included.',['SGA4III'],['S31-18.3','L31-comparison'],source='K31-03')
c(514,[],[98],'303','Extend to noncommutative H¹ and H².','The manuscript asks for nonabelian analogues of the preceding smooth-base-change and separably-closed-extension comparisons. Degree1 means torsors; degree2 requires the chosen gerbe/band formulation, not an abelian derived-functor group.','open on the pages','C','SGA4 XVI1.1 includes the nonabelian degree1 comparison with the appropriate local1-asphericity input. XVI1.4(b) explicitly discusses the nonabelian H² extension as an expected elaboration; no exact later theorem for the unspecified banded formulation was identified in this search.',['SGA4III'],['S31-18.3','S31-18.4','L31-comparison'],source='K31-03',confidence='medium')
c(515,[],[98],'305–308','Relative purity for a smooth closed subscheme of a smooth family.','For smooth X/S and a smooth closed Y/S of pure relative codimension c, with locally constant coefficients killed by an integer invertible on S, the local-cohomology sheaves vanish except in degree2c and the surviving sheaf is F|Y(−c).','stated without proof','A','Exact SGA4 XVI3.7–3.8, including the Tate twist. The unspecified degree and orientation symbol on the leaf are supplied only in the modern formulation.',['SGA4III'],['S31-18.3','L31-comparison'],source='K31-03')
c(516,[],[99],'313–345','Three local-constancy conditions, linked by duality and localization.','The page relates local constancy of Rh_*(F|V), Rh_!(F′|V), and Rg_*(F′|Y), where F′=Hom(F,I_X/S). To make this a theorem one must retain the preceding smooth/proper family, finite invertible coefficients, and a dualizing complex in the correct derived degree. These hypotheses are not fully reproduced on this sheet.','proof sketched with missing ambient setup','C','SGA4 XVIII duality and XVI smooth base change support precisely formulated versions. The displayed localization sequence naturally compares f_*F′,h_!F′,g_*F′; the source’s association of (i) rather than(ii) with that sequence may be a label slip. An unqualified equivalence for arbitrary X/S is not established.',['SGA4III'],['S31-18.3','S31-19.1','L31-comparison'],source='K31-03',confidence='medium')
c(517,[],[99],'320–334','Give an elementary-morphism case; perhaps flat normal-crossings fibers suffice.','The author proposes extending the local-constancy assertion from smooth Y/S to a flat family whose fibers have normal-crossing singularities, and requests a formulation for an elementary morphism. Fiberwise normal-crossings alone leaves the relative strata and variation unspecified.','open on the pages','C','SGA4 XVI and XVIII provide smooth base change and duality, while ILO treats tame/nearby-cycle refinements. No exact match was found for the raw fiberwise condition; a strict relative normal-crossings pair with smooth strata is a plausible controlled formulation. This is a reconstruction, not a source theorem.',['SGA4III','ILO2014'],['S31-19.1','S31-19.2','L31-comparison'],source='K31-03',confidence='medium')
c(518,[],[101],'386–405','G only on V; wild ramification complicates local constancy; codimension≥2 causes no trouble.','For i:V=X−Y→X, the Leray spectral sequence R^pf_*(R^qi_*G)⇒R^(p+q)h_*G reduces local constancy to that of its terms. Wild ramification obstructs a naive smooth-boundary theorem. Finite locally constant G extends across codimension≥2 when the ambient scheme is regular and the purity hypotheses hold; codimension alone on a singular normal X does not suffice.','open on the pages with a qualified purity assertion','C','SGA1 X3.1 gives Zariski–Nagata purity in the regular setting; SGA4 XV–XVI supplies the tame/local-acyclic context. The page itself names wild ramification as the obstacle. No uniform wild theorem is inferred from smoothness of Y/S alone.',['SGA1','SGA4III','ILO2014'],['S31-19.2','S31-19.3','L31-comparison'],comp='Leray bidegrees are(p,q) with total p+q. Extension of a finite locally constant sheaf is equivalent to extension of its finite étale trivializing cover; purity removes a codimension≥2 branch locus only under its regularity assumptions.',source='K31-03')
c(519,[],[100],'356–379','Noetherian normal rings are Krull; essential valuations are normalized.','For an integral domain A, noetherian plus integrally closed implies Krull. In a Krull domain the essential valuations at height-one primes are normalized discrete valuations and detect membership by v_P(x)≥0. The word domain is necessary and is supplied by the surrounding fraction-field notation.','proof sketched on Bourbaki typescript','E','The leaf is a reused Bourbaki-style chapterVII typescript. Heinzer–Rotthaus–Wiegand2020§2.11–2.18 states these classical Krull facts. A bibliographic trace identifies Bourbaki Algèbre commutative chapterVII publication1965, but this run does not date the typescript from that publication.',['HeinzerRotthausWiegand2020','BourbakiACVII'],['S31-14.2','S31-20.1','L31-krull'],comp='For an extremal divisor P, the divisorial ideals for P and2P are strictly nested. Choose x in their difference: div(x)≥P but not≥2P, so v_P(x)=1. The uncertain relation must be not≥, not merely≠, for this argument.',source='K31-03')
c(520,[],[102],'414–416','The finite intersection of Krull subrings of a field is Krull.','If R1,…,Rn are Krull subrings of a common field F, then S=∩Rj is Krull, even if their fraction fields differ. Restrict all essential valuations to FracS, discard trivial restrictions, normalize the nontrivial discrete value subgroups, and retain finite character because n is finite.','proved there','E','This is the classical intersection theorem; the valuation definition in Heinzer–Rotthaus–Wiegand2020§2.11 gives exactly the reconstruction used on the typescript. Their§9.7 also uses intersection stability. The draft’s family(v_ji) after defining w_ji is a notational slip to scan-check.',['HeinzerRotthausWiegand2020','BourbakiACVII'],['S31-20.1','L31-krull'],comp='Each restricted value group is0 or a subgroup mZ of Z. Divide bym for normalization. For fixed0≠s∈S only finitely many valuations from each Rj are nonzero, so the union over finitely many j is finite. Membership follows from simultaneous nonnegative valuations.',source='K31-03')
c(521,[],[102],'418','Intersection with a subfield is Krull.','If A is a Krull domain and K′⊂FracA is a subfield, then A∩K′ is a Krull domain. The fraction field of the intersection need not equal K′; restrict valuations to its actual fraction field.','proved by the preceding intersection argument','E','This is the standard subfield-intersection consequence of the Krull valuation characterization. The field K′ is itself Krull with an empty essential-valuation family, or one can restrict the valuations of A directly.',['HeinzerRotthausWiegand2020','BourbakiACVII'],['S31-20.1','L31-krull'],source='K31-03')
c(522,[],[102,100],'420–436;354–364','Krull iff completely integrally closed and maximal condition on integral divisorial ideals.','An integral domain A is Krull iff it is completely integrally closed and satisfies ACC on nonzero integral divisorial ideals. Complete integral closure cannot be weakened to ordinary integral closure without further conditions.','proof split across the two reused leaves, with intervening text missing','E','Heinzer–Rotthaus–Wiegand2020§2 and classical Mori-domain characterizations provide the established result; the exact ACC statement is additionally checked in the opened literature listed in the search log. The typescript gives only the beginning and end of the proof.',['HeinzerRotthausWiegand2020','BourbakiACVII'],['S31-8.4','S31-20.1','L31-krull'],comp='For a Krull valuation family, v_i(a)=sup_(a⊂Ax)v_i(x) is bounded above by v_i(a0) for any fixed nonzero a0∈a. The source’s principal-containment implication is checked; the absent middle of the converse is not reconstructed as his proof.',source='K31-03')
c(523,[468],[44],'1424–1433','Refinement of the questioned residual H¹ comparison (this run).','If O is local Artin, G finite acts on O, and |G| is invertible in O, then H¹(G,O×)→H¹(G,κ×) is an isomorphism. This is a proved sufficient refinement of the source question, not a theorem stated by him; it does not by itself replace G by inertia without taking residual invariance into account.','reconstruction of a sufficient refinement, absent from the page','E','Standard finite-group averaging and the nilpotent filtration prove this tame Artin-local case. It is explicitly separated from the false wild comparison CL-SA12-456.',['MilneCFT','AKO'],['S31-12.1','S31-12.2','L31-group'],comp='The filtration1+m^r has successive quotients m^r/m^(r+1), additive G-modules. Multiplication by|G| is invertible, so every positive group-cohomology group of these quotients vanishes. Inductively H¹ and H² of1+m vanish; 1→1+m→O×→κ×→1 then gives the claimed isomorphism.')
c(524,[483],[50],'1584–1591','Refinement of the regular-representation norm argument (this run).','For Γ=(Fℓ)^r, a nontrivial translation in the regular representation has determinant(−1)^((ℓ−1)ℓ^(r−1)). The determinant is identically1 except Γ=C2. For every finite representationρ,ρ⊕det(ρ)^(−1) has determinant1 and remains faithful whenρ is faithful.','reconstruction correcting the page’s excluded case','E','The determinant identity is an elementary cycle calculation. The additional one-dimensional character repairs the embedding in a norm-one torus after a corresponding product construction; it changes the stated torus dimension and does not complete the draft’s final induction automatically.',['MilneAG2017'],['S31-13.3','L31-structure'],comp='programs/check_calculations.py; outputs/calculations.json#regular_norm. A translation decomposes into ℓ^(r−1) cycles of lengthℓ. Multiplying by the inverse determinant makes the block determinant exactly1.')
c(525,[],[57],'99–122','Restriction of an injective sheaf to a closed subset need not be flasque.','Let X be the union of two irreducible curves X1,X2 meeting at one point p, and I the sheaf of arbitrary Q-valued functions on X. It is a product of injective skyscraper sheaves, hence injective. Its restriction to Y=X1∪X2 in the related ambient construction need not be flasque: the function0 on one punctured branch and1 on the other cannot extend across p as an ambient germ. This is a distinction between inverse image and naive pointwise restriction.','proof sketched','C','The manuscript gives an explicit germ obstruction; general sheaf references confirm that inverse image need not preserve injectives or flasqueness. The exact ambient two-branch configuration and restriction maps are retained in the proof certificate, not replaced by an assertion that the sheaf of all functions itself is nonflasque.',['Stacks03F9','SGA4V'],['S31-6.2','S31-16.1'],comp='See outputs/calculations.json#closed_restriction and the full construction in CL-SA12-475–476. The all-functions sheaf on the ambient irreducible component is injective; the incompatible0/1 germs arise after restriction to the closed reducible intersection.',source='K31-01',confidence='medium')

c(526,[],[56],'92','On an irreducible curve the induced sheaf is always flasque, facile.','The draft claims that restricting the ambient injective sheaf to an irreducible algebraic curve gives a flasque sheaf. The intended ambient class and whether the assertion concerns every injective or the particular all-functions construction are compressed. The examples establish that irreducibility alone in higher dimension does not suffice.','stated without proof','C','General sheaf references distinguish restriction from preservation of injectivity/flasqueness. This search found no exact theorem under the draft’s incomplete quantifiers; the line is retained as an open verification rather than used as a premise of the explicit nonzero H¹ construction. The latter only needs its displayed non-surjectivity, not surjectivity at the next cohomology term.',['SGA4V','Stacks03F9'],['S31-6.2','S31-16.1'],source='K31-01',confidence='low')

# Targeted corrections after opening the exact published statements.
for q in C:
 if q['id']=='CL-SA12-401':
  q['fate']='The finite-flat-site comparison remains unidentified. Milne ADT III introduction explicitly cites Shatz1966 for unbounded torsion flat-sheaf cohomology over imperfect fields; this shows why restricting to finite representable groups and fixing the topology matters. Shatz metadata and Milne’s statement were opened; Shatz full text was not obtained.'
  q['refs'].append('Shatz1966')
  q['query_ids']+=['S31-14.1','S31-15.1','S31-15.2']
 if q['id']=='CL-SA12-425':
  q['statement']+=' For the comparison invoked here retain constructible torsion coefficients, or the properness alternative in SGA4 XVI4.1; arbitrary torsion on an arbitrary nonproper complex variety is not covered by that theorem.'
 if q['id']=='CL-SA12-502':
  q['fate']='Gabber–Orgogozo2008 theorem6.1 proves the stronger equality cd_p(U_et)=dimA+dim_p(k) for every nonempty affine U⊂Spec(A[1/p]), with A excellent henselian integral of mixed characteristic. Here dim_p(k) is Kato’s differential p-dimension, between p-rank and p-rank+1, not ordinary Galois cd_p(k). This matches a major part of the draft after the residue characteristic is inverted; the stated all-affine-open formulation, including opens meeting V(p), and its exact δ+cd coefficient require a further comparison and are not declared solved.'
  q['fate_date']='arXiv0706.0671 first submitted2007-06-05; opened author version2008-03-27; Inventiones174(2008),47–80.'
 if q['id']=='CL-SA12-410':q['confidence']='high'
 if q['id']=='CL-SA12-406':q['lines']='MPL_31_002-051_transcription.tex:156–161'
 if q['id']=='CL-SA12-439':q['lines']='MPL_31_002-051_transcription.tex:896–905'
 if q['id']=='CL-SA12-438':
  q['refs'].append('Murre1964')
  q['fate']+=' Murre1964 introduction and theorem1.2.1 were checked: the criterion is for group-valued functors with seven axioms, and its Picard application explicitly assumes a proper algebraic scheme. It is not an exact solution of the nonproper programme.'
 if q['id']=='CL-SA12-428':
  q['refs'].append('GabberOrgogozo2008');q['fate']+=' Gabber–Orgogozo1.2 supplies the later excellent henselian mixed-characteristic Kato-dimension theorem, with different coefficient conventions; the raw overwritten clauses still require formulation.'
 if q['id']=='CL-SA12-479':
  q['refs'].append('GabberOrgogozo2008');q['fate']+=' Gabber–Orgogozo§2.1.1 independently confirms finite-extension invariance of p-rank; this does not identify the undefined relative defect.'
 if q['id'] in ['CL-SA12-448','CL-SA12-452','CL-SA12-453']:
  q['refs'].append('Broue2007')
  q['fate']+=' Broué2007§6.8 and the group-algebra example printed55 give the relative trace criterion; its bibliography distinguishes Higman’s1954 Modules with a group of operators (369–376) from Indecomposable representations at characteristic p (377–381). This historical reference does not validate the false stable-corestriction clause.'
 if q['id']=='CL-SA12-522':
  q['refs'].append('Chang2021')
  q['fate']='The classical characterization is stated explicitly in Chang2021, proof of theorem4.1, with Mori defined as ACC on divisorial ideals in§2; its backward reference is Houston–Zafrullah theorem2.3. Heinzer–Rotthaus–Wiegand2020§2 supplies the valuation and divisor-group formulation. The Bourbaki typescript gives only the beginning and end of the proof; its1965 chapter metadata is verified through Nicolas1966–67 reference3.'
 if q['id']=='CL-SA12-503':
  q['statement']='Let X→S be flat and U⊂X open, with U_s schematically dense in X_s for every s. The draft assumes either X locally noetherian, or X→S locally finitely presented and U retrocompact, and concludes that U is schematically dense in X.'
  q['fate']='SGA3IX4.6 publishes a stronger statement: retrocompactness is removed from the theorem and used only for simplicity in the displayed proof; the general case is referred to EGAIV3,11.10.10 and11.9.17. The source draft really includes retrocompactness in its second alternative (raw line599); this is a mathematical strengthening in print, not an ink correction.'
 if q['id']=='CL-SA12-514':
  q['fate']='The programme has a precise modern solution: Haine–Holzschuh–Wolf2024 theorem0.1/corollary2.30 proves smooth (indeed prosmooth) base change for Σ-torsion étale sheaves of spaces on qcqs schemes, with Σ the invertible primes and torsion defined in1.9 as a truncated filtered colimit of constructible Σ-torsion objects. This includes the finite prime-to-characteristic gerbe framework and higher nonabelian refinements. Their proof explicitly uses Giraud1971VII2.1.2 for sheaves of groupoids. The raw page does not fix a band or coefficient class, so no unrestricted nonabelianH² statement is inferred.'
  q['refs'].append('HaineHolzschuhWolf2024');q['query_ids']+=['S31-18.4','S31-22.1'];q['class']='B';q['confidence']='high'
  q['fate_date']='Haine–Holzschuh–Wolf arXiv2304.00938 first2023-04-03, revised2024-06-06; accepted2024-10-09, first published2024-12-04; Journal of Topology17(2024),e70009.'
 if q['id']=='CL-SA12-518':
  q['fate']='SGA1X3.1 gives purity in the regular setting. A precise later controlled wild case is Achinger2017 corollary2.3: for a smooth projective geometrically connected curve family with a section and a finite locally constant F_ℓ-sheaf on its complement, constant Swan conductor at the section makes all ordinary and compactly supported higher direct images locally constant and compatible with base change. Example1.2 exhibits base-change failure for an Artin–Schreier sheaf under A²→A¹ projection. These exact results explain the need to control ramification; they do not settle the manuscript’s unspecified higher-dimensional programme.'
  q['refs'].append('Achinger2017');q['query_ids']+=['S31-21.1','S31-19.4']
  q['fate_date']='Achinger arXiv1701.03197 first2017-01-12, revised2017-05-04; published online2017-05-17, Inventiones210(2017),453–499.'
 if q['id']=='CL-SA12-505':
  q['fate']='SGA3IX4.7–4.9 establishes density and the equality tests. Remark4.10 completes the source’s truncated final condition: the subgroups killed by m^r suffice when at every residue characteristic m is not a pure power of that characteristic and every prime divisor of the torsion of the character type divides m. This is the published continuation, not supplied manuscript text.'
 if q['id']=='CL-SA12-525':
  q['statement']='Let X be an irreducible space containing two irreducible closed curves Y1,Y2 meeting only at p, and let I be the sheaf of arbitrary Q-valued functions on X. It is a product of injective skyscraper sheaves. Set Y=Y1∪Y2. The section of I|_(Y−{p}) equal to the constant germ0 on Y1−{p} and1 on Y2−{p} does not extend to Y: an ambient function representing a germ at p would have to be0 and1 on two nonempty intersecting open neighborhoods. Thus I|Y is not flasque.'
 q['present_status']='As of2026-11-19: '+q['fate']

